insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('si-waass-genau-wos-tuad-si-gibd-eam-koid-woam-und-ea-schbringd-a-jeeds-moi-drauf-au', 'Si waass genau wos tuad - si gibd eam koid-woam, und ea schbringd a jeeds Moi drauf au!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Sie weiß genau, was sie tut – sie gibt ihm kalt-warm, und er springt ein jedes Mal darauf an!', '[{"kategorie": "wörtlich", "text": "\"Sie weiß ganz genau, wie sie ihn zappeln lässt – mal lockt sie ihn, mal stößt sie ihn weg, und er fällt jedes Mal darauf rein!\"  2. Sie spielt ein durchtriebenes Spiel mit ihm – mal Nähe, mal Kälte, und er macht jedes Mal mit!  3. Sie tanzt mit ihm auf der Klaviatur der Gefühle – erst heiß, dann eiskalt. Und er tanzt brav mit!"}]'::jsonb, 'wem koid-woam geem'),
  ('dem-wear-i-koid-woam-geem', 'Dem wear I koid-woam geem!', '', '', '', 'Wiener Gaunersprache', 'Dem werde ich kalt-warm geben!', '[{"kategorie": "wörtlich", "text": "\"Dem werde ich Feuer unter dem Hintern machen!\"  2. \"Dem werde ich die Hölle heißmachen!\"  3. \"Dem werde ich die Hölle auf Erden bereiten!\""}]'::jsonb, ''),
  ('sogoa-im-haeaefn-kriagsd-jetztd-kooschares-fleisch', 'Sogoa im Hääfn kriagsd jetztd kooschares Fleisch!', '', '', '', 'Wiener Gaunersprache', 'Sogar im Häfen kriegst du jetzt koscheres Fleisch!', '[{"kategorie": "wörtlich", "text": "\"Sogar im Gefängnis gibt''s jetzt koscheres Fleisch!\"  2. Selbst in Haft bekommst du jetzt koschere Mahlzeiten!  3. Mittlerweile gibt es sogar in Justizanstalten koschere Kost!"}]'::jsonb, ''),
  ('ned-kooscha-sei', 'ned kooscha sei', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'nicht koscher sein', '[{"kategorie": "wörtlich", "text": "\"nicht einwandfrei sein\""}, {"kategorie": "rel.", "text": "\"rituell unrein\", \"zum Verzehr ungeeignet\", \"nach jüdischem Ritus befleckt\", \"nach den jüdischen Speisegesetzen [Kashrut] unrein und daher zum Verzehr nicht erlaubt\""}, {"kategorie": "fig.", "text": "suspekt, bedenklich, nicht ganz geheuer"}]'::jsonb, 'Des Fleisch iss I ned - des is ned kooscha!'),
  ('des-fleisch-iss-i-ned-des-is-ned-kooscha', 'Des Fleisch iss I ned - des is ned kooscha!', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'Das Fleisch ess ich nicht - das ist nicht koscher!', '[{"kategorie": "wörtlich", "text": "\"Das ist kein koscheres Fleisch – also kommt’s für mich nicht infrage!\"  2. Ich ess vieles, aber Unkoscheres kommt mir nicht auf den Teller!  3. Ich darf das Fleisch nicht essen – es entspricht nicht den jüdischen Kaschrut-Vorschriften!"}]'::jsonb, 'ned kooscha sei'),
  ('dea-dillo-do-is-ma-ned-gaunz-kooscha', 'Dea Dillo do is ma ned gaunz kooscha!', '', '', '', 'Wiener Gaunersprache', 'Der Dillo da ist mir nicht ganz koscher!', '[{"kategorie": "wörtlich", "text": "\"Der Typ da ist mir nicht ganz koscher!\"  2. Der Dolm da ist mir nicht ganz geheuer!  3. Der Heini da kommt mir nicht ganz sauber vor!"}]'::jsonb, 'ned kooscha sei'),
  ('ois-kooscha', 'Ois kooscha!', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'Alles koscher!', '[{"kategorie": "wörtlich", "text": "\"Alles in Ordnung!  (von jiddisch \"koscher\"=\"einwandfrei\")"}, {"kategorie": "", "text": "Alles okay!  3. \"Alles roger!\"  4. [[Ois]] leiwaund!"}]'::jsonb, ''),
  ('ois-leiwaund', 'Ois leiwaund!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Alles leinwand!', '[{"kategorie": "wörtlich", "text": "\"Alles in bester Ordnung!\" (gaunersprachlich ursprünglich der Ausruf des wachestehenden Komplizen, der mit dem Zuruf \"Leiwaund!\" den anderen Mittätern signalisierte, dass \"alles perfekt wie auf einer schneeweißen Leinwand ist\", d.h. keinerlei Gefahr droht)  2. Alles okay!  3. \"Alles roger!\"  4. [[Ois]] kooscha!"}]'::jsonb, ''),
  ('a-kooschara-buasch', 'a kooschara Buasch', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'ein koscherer Bursch', '[{"kategorie": "wörtlich", "text": "\"ein koscherer Bursche\""}, {"kategorie": "", "text": "ein anständiger Junge"}, {"kategorie": "", "text": "ein ehrlicher Charakter"}]'::jsonb, 'Vatrau ma - dea schaud zwoa wüüd aus, is owa a kooschara Buasch!'),
  ('vatrau-ma-dea-schaud-zwoa-wueued-aus-is-owa-a-kooschara-buasch', 'Vatrau ma - dea schaud zwoa wüüd aus, is owa a kooschara Buasch!', '', '', '', 'Wiener Gaunersprache', 'Vertrau mir - der schaut zwar wild aus, ist aber ein koscherer Bursch!', '[{"kategorie": "wörtlich", "text": "\"Glaub mir – der sieht zwar wild aus, ist aber ein grundanständiger Typ!\"  2. Lass dich nicht von seinem Aussehen täuschen – er ist im Grunde ein ganz ehrlicher Charakter!  3. Vertrau mir – er macht vielleicht einen wilden Eindruck, aber er ist ein kreuzbraver Mensch!"}]'::jsonb, ''),
  ('a-kooschara-diil', 'a kooschara Dììl', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'ein koscherer Deal', '[{"kategorie": "wörtlich", "text": "\"ein blitzsauberer Deal\""}, {"kategorie": "", "text": "ein lupenreines Geschäft"}, {"kategorie": "", "text": "eine blitzblanke Transaktion"}]'::jsonb, ''),
  ('moch-da-kaane-suang-des-woa-von-vuan-bis-hint-a-kooschara-diil', 'Moch da kaane Suang - des woa von vuan bis hint a kooschara Diil!', '', '', '', 'Wiener Gaunersprache', 'Mach dir keine Sorgen – das war von vorne bis hinten ein koscherer Deal!', '[{"kategorie": "wörtlich", "text": "\"Mach dir keine Sorgen – das war ein koscherer Deal von Anfang bis Ende!\"  2. Du brauchst dir keine Gedanken machen – das war ein vollkommen sauberes, korrektes und vertrauenswürdiges Geschäft!  3. Mach dir keinen Kopf – der Deal war absolut wasserdicht!"}]'::jsonb, ''),
  ('si-ned-kooscha-fueuen', 'si ned kooscha füün', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'sich nicht koscher fühlen', '[{"kategorie": "wörtlich", "text": "\"sich nicht wohl fühlen\""}, {"kategorie": "", "text": "\"ein ungutes Gefühl haben\""}, {"kategorie": "", "text": "\"sich unbehaglich fühlen\""}]'::jsonb, 'Bei dera Partii hob I mi nii gaunz kooscha gfüüd!'),
  ('bei-dera-partii-hob-i-mi-nii-gaunz-kooscha-gfueued', 'Bei dera Partii hob I mi nii gaunz kooscha gfüüd!', '', '', '', 'Wiener Gaunersprache', 'Bei dieser Partie hab ich mich nie ganz koscher gefühlt!', '[{"kategorie": "wörtlich", "text": "\"Bei dieser Truppe hab ich mich nie ganz wohl gefühlt!\"  2. In der Truppe hatte ich von Anfang an kein gutes Gefühl!  3. Die Bande war mir von Anfang an nicht ganz geheuer!"}]'::jsonb, 'si ned kooscha füün'),
  ('an-krawaeu-mochn', 'an Krawäu mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Krawall machen', '[{"kategorie": "wörtlich", "text": "\"einen Höllenlärm machen\""}, {"kategorie": "", "text": "\"ein Getöse verursachen\""}, {"kategorie": "", "text": "\"einen Wirbel machen\""}, {"kategorie": "", "text": "\"ein Theater machen\""}]'::jsonb, 'De mochn a so an Krawäu, dass de Hee scho dreimoi augruckd is!'),
  ('de-mochn-a-so-an-krawaeu-dass-de-hee-scho-dreimoi-augruckd-is', 'De mochn a so an Krawäu, dass de Hee scho dreimoi augruckd is!', '', '', '', 'Wiener Gaunersprache', 'Die machen so einen Krawall, dass die Höh schon dreimal angerückt ist!', '[{"kategorie": "wörtlich", "text": "\"Die machen einen derartigen Lärm, dass die Polizei schon dreimal dagewesen ist!\"  2. Die machen einen solchen Krach, dass schon dreimal die Bullen da waren!  3. Die machen so ein Getöse, dass die Polizei schon dreimal anrücken musste!"}]'::jsonb, 'an Krawäu mochn'),
  ('waunn-de-zwaa-zsaummkumma-gibds-imma-an-krawaeu', 'Waunn de zwaa zsaummkumma, gibds imma an Krawäu!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn die zwei zusammenkommen, gibt''s immer einen Krawall!', '[{"kategorie": "wörtlich", "text": "\"Wenn die zwei aufeinandertreffen, ist Krawall vorprogrammiert!\"  2. Wenn die beiden sich begegnen, gibt''s immer Streit!  3. Treffen die beiden aufeinander, gibt''s jedes Mal Zoff!"}]'::jsonb, ''),
  ('de-krood-is-nua-auf-krawaeu-aus', 'De Krood is nua auf Krawäu aus!', '', '', '', 'Wiener Gaunersprache', 'Diese Kröte ist nur auf Krawall aus!', '[{"kategorie": "wörtlich", "text": "\"Dieser Fiesling ist nur auf Streit aus!\"  2. Dieser Ungustl ist nur darauf aus, Unruhe zu stiften!  3. Dieser Stinkstiefel sucht nur Zoff!"}]'::jsonb, ''),
  ('moch-ned-so-an-krawaeu', 'Moch ned so an Krawäu!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Mach nicht so einen Krawall!', '[{"kategorie": "wörtlich", "text": "\"Mach nicht so einen Wirbel!\"  2. \"Mach keinen solchen Radau!\"  3. \"Mach kein solches Theater!\"  4. \"Mach nicht so viel Aufhebens!\""}]'::jsonb, ''),
  ('bua-putz-da-de-groigaln-aus-de-aung-bevuasd-ind-schui-geesd', 'Bua, putz da de Groigaln aus de Aung, bevuasd ind Schui geesd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Bub, putz dir die Groikerln aus den Augen, bevor du in die Schule gehst!', '[{"kategorie": "wörtlich", "text": "\"Junge, putz dir die Schlafkörnchen aus den Augen, bevor du in die Schule gehst!\"  2. Bub, wisch dir den Schlafsand aus den Augen, bevor du zur Schule gehst!  3. Junge, mach erst die Augen frei - die Sandmännchenreste gehören nicht mit in die Schule!"}]'::jsonb, ''),
  ('host-de-kuaraasch-oda-ned', 'Host de Kuaraasch oda ned?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Hast du die Courage oder nicht?', '[{"kategorie": "wörtlich", "text": "\"Traust du dich oder nicht?\"  2. \"Hast du die Schneid oder nicht?\"  3. \"Bringst du den Mut auf oder nicht?\"  4. \"Hast du die Eier oder nicht\"?"}]'::jsonb, ''),
  ('bevuara-si-zu-seina-schwiigamuada-traud-schdessda-si-imma-easchd-a-poa-schluck-kuaraaschiwossa-ind-figua', 'Bevuara si zu seina Schwiigamuada traud, schdessda si imma easchd a poa Schluck Kuaraaschiwossa ind Figua!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Bevor er sich zu seiner Schwiegermutter traut, stößt er sich immer erst ein paar Schlucke ''Courage-Wasser'' in die Figur!', '[{"kategorie": "wörtlich", "text": "\"Bevor er sich zu seiner Schwiegermutter wagt, kippt er sich immer erst ein paar Schlucke ''Mutwasser'' hinter die Binde!\"  2. Zu seiner Schwiegermutter traut er sich erst, wenn er sich vorher ein paar Stamperl ''Mutmacher'' genehmigt hat!  3. Die Schwiegermutter erträgt er nur, wenn er sich vorher etwas flüssige Courage gegönnt hat!"}]'::jsonb, ''),
  ('wia-soong-zu-oim-wos-a-waazige-haud-hod-und-wiara-frosch-ausschaud-imma-nua-krood-egal-ob-eadkrood-oda-unkn', 'Wia soong zu oim, wos a waazige Haud hod und wiara Frosch ausschaud, imma nua ''Krood'' - egal ob Eadkrood oda Unkn!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Wir sagen zu allem, was eine warzige Haut hat und wie ein Frosch ausschaut, immer nur ''Kröte'' - egal ob Erdkröte oder Unke!', '[{"kategorie": "wörtlich", "text": "\"Alles, was warzige Haut hat und froschartig aussieht, nennen wir schlicht ‚Kröte‘ – ob es nun eine Erdkröte ist oder eine Unke!\"  2. Alles, was warzig ist und irgendwie wie ein Frosch aussieht, läuft bei uns automatisch unter ‚Kröte‘ – egal, was es genau ist!  3. Für uns heißt jedes Tier mit warziger Haut und Froschgestalt einfach nur ‚Kröte‘ – unabhängig davon, ob es eine Erdkröte oder eine Unke ist!"}]'::jsonb, ''),
  ('a-so-a-oide-krood', 'A so a oide Krood!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'So eine alte Krot!', '[{"kategorie": "wörtlich", "text": "\"So eine gemeine alte Kröte!\"  2. Was für eine böse, alte [[Schachtel]]!  3. So eine widerwärtige, alte [[Grammel]]!"}]'::jsonb, ''),
  ('de-krood-fressn', 'de Krood fressn', '', '', '', 'Wiener Sprüche, die sitzen!', 'die Krot fressen', '[{"kategorie": "wörtlich", "text": "\"die Kröte fressen\" (eine unangenehme oder demütigende Situation hinnehmen müssen)"}, {"kategorie": "", "text": "\"in den sauren Apfel beißen\""}, {"kategorie": "", "text": "\"die bittere Suppe auslöffeln\""}]'::jsonb, 'Aum End hoda de Krood gfressn und de gaunze Zech allaa zoid!'),
  ('aum-end-hoda-de-krood-gfressn-und-de-gaunze-zech-allaa-zoid', 'Aum End hoda de Krood gfressn und de gaunze Zech allaa zoid!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Am Ende hat er die Krot gefressen und die ganze Zeche bezahlt!', '[{"kategorie": "wörtlich", "text": "\"Am Ende musste er in den sauren Apfel beißen und die gesamte Rechnung allein begleichen!\"  2. Schlussendlich hat er die bittere Pille geschluckt und die ganze Zeche allein bezahlt!  3. Schließlich hat er den sauren Bissen geschluckt und die gesamte Zeche allein bezahlt!"}]'::jsonb, 'de Krood fressn'),
  ('de-krood-schlickn', 'de Krood schlickn', '', '', '', 'Wiener Sprüche, die sitzen!', 'die Krot schlucken', '[{"kategorie": "wörtlich", "text": "\"die Kröte schlucken\" (eine unangenehme oder demütigende Situation hinnehmen müssen)"}, {"kategorie": "", "text": "\"in den sauren Apfel beißen\""}, {"kategorie": "", "text": "\"die bittere Suppe auslöffeln\""}]'::jsonb, 'De Krood muassd schlickn!'),
  ('de-krood-muassd-schlickn', 'De Krood muassd schlickn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Krot musst du schlucken!', '[{"kategorie": "wörtlich", "text": "\"Diese Kröte musst du schlucken!\"  2. (fig.) \"Diese bittere Suppe musst du auslöffeln!\"  3. \"In diesen sauren Apfel musst du beißen!\""}]'::jsonb, 'de Krood schlickn'),
  ('de-kroodnbleetschn-is-ans-vond-easchdn-bleamaln-de-im-lenz-blian', 'De Kroodnbleetschn is ans vond easchdn Bleamaln, de im Lenz blian!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Die Krötenplätschen ist eine der ersten Blümchen, die im Lenz blühen!', '[{"kategorie": "wörtlich", "text": "\"Der Huflattich ist eine der ersten Blumen, die im Frühjahr blühen!\"  2. Der Huflattich zählt zu den frühesten Blütenpflanzen im Frühjahr!  3. Der Huflattich ist eine der ersten Blumen, die im Frühling aufgehen!"}]'::jsonb, ''),
  ('wea-mid-so-an-kroodnfeidl-daheakummd-ghead-damit-eignhaendich-rasiad', 'Wea mid so an Kroodnfeidl daheakummd, ghead damit eignhändich rasiad!', '', '', '', 'Wiener Gaunersprache', 'Wer mit so einem Krötenmesser ankommt, gehört damit eigenhändig rasiert!', '[{"kategorie": "wörtlich", "text": "\"Wer mit so einem Krötenmesser antanzt, gehört damit eigenhändig rasiert!\"  2. Wer mit so einem Schrottmesser anrückt, dem gehören die Haare damit abgeraspelt!  3. Wer so ein Gulaschschwert anschleppt, gehört damit am Sack rasiert!"}]'::jsonb, ''),
  ('in-da-kroodnlockn-quaakn-d-fresch-wiara-hoade-bsoffana-de-gaunze-nochd-duach', 'In da Kroodnlockn quaakn d''Fresch wiara Hoade Bsoffana de gaunze Nochd duach!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'In der Krötenlacke quaken die Frösche wie eine Horde Besoffener!', '[{"kategorie": "wörtlich", "text": "\"Im Krötentümpel quaken die Frösche wie eine Horde Besoffener die ganze Nacht hindurch!\"  2. Im Krötenteich gröhlen die Frösche Nacht für Nacht wie eine Horde Feierwütiger nach dem zehnten Bier!  3. Im Sumpfloch quaken die Frösche pausenlos wie eine Meute besoffener Proleten!"}]'::jsonb, ''),
  ('a-grooda-michl', 'a grooda Michl', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein gerader Michl', '[{"kategorie": "wörtlich", "text": "\"ein gerader Kerl\""}, {"kategorie": "", "text": "\"ein ehrlicher Bursche\""}, {"kategorie": "", "text": "\"ein aufrichtiger Charakter\""}, {"kategorie": "", "text": "\"eine ehrliche Haut\" (offener geradliniger Mensch, der nicht schöntut und sich nicht verstellt)"}]'::jsonb, 'Da Vinz is a grooda Michl - dea reed nix schee!'),
  ('da-vinz-is-a-grooda-michl-dea-reed-nix-schee', 'Da Vinz is a grooda Michl - dea reed nix schee!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Vinzenz ist ein gerader Michl - der redet nichts schön!', '[{"kategorie": "wörtlich", "text": "\"Der Vinzenz ist ein ehrlicher, direkter Mensch - der nennt die Dinge beim Namen!\"  2. Der Vinzenz ist ein gerader Kerl – der sagt’s so, wie’s ist!  3. Der Vinzenz ist eine ehrliche Haut - der sagt dir die Wahrheit ins Gesicht!"}]'::jsonb, 'a grooda Michl'),
  ('mischlaeu-mandal', 'Mischläu-Mandal', 'das', '', '', 'Echte Wiener Schmähperlen', 'Michelin-Manderl', '[{"kategorie": "wörtlich", "text": "\"Michelin-Männchen\" (Werbefigur des Reifenherstellers \"Michelin\")"}, {"kategorie": "allg.", "text": "\"Bib\", \"Bibendum\" (=offizieller Name des \"Michelin-Manderls\": Auf der Weltausstellung 1894 in Lyon fiel dem Firmengründer Édouard Michelin ein Stapel Autoreifen verschiedener Größen auf, die in weiße Stoffhüllen verpackt waren. Er machte seinen Bruder André darauf aufmerksam: „Wenn er Arme hätte, sähe er fast wie ein Mensch aus.“ Dann fiel ihm ein Plakat ein, das einen dicken Bayern mit einer Maß Bier und dem lateinischen Spruch „Nunc est bibendum!“ – deutsch „Jetzt lasst uns trinken!“ – zeigte. Daraufhin ließen die Brüder ein Plakat mit einem dicken Reifenmann entwerfen, der eine mit Glassplittern und Nägeln gefüllte Schale hochhebt, und der Inschrift: „Nunc est bibendum!.. C’est-[[-dire]]: À votre santé! Le pneu Michelin boit l’obstacle!“ [„Nunc est bibendum! Das heißt: Auf Ihr Wohl! Der Michelin-Reifen schluckt das Hindernis!“])"}, {"kategorie": "fig., scherzhaft für", "text": "\"dick Eingepackter\", \"Aufgepumpter\", \"Überproportionierter\", [[Mehlsackl]] (=Mann, der einen dicken Daunenanorak, etc. anhat und deshalb unvorteilhaft bzw. unnatürlich dick aussieht)"}]'::jsonb, 'Im Winta kumm I ma unta meine siem Schichtn vua wiara Mischläu-Mandal!'),
  ('ausschaun-wiara-mischlaeu-mandal', 'ausschaun wiara Mischläu-Mandal', '', '', '', 'Wiener Sprüche, die sitzen!', 'ausschauen wie ein Michelin-Manderl', '[{"kategorie": "wörtlich", "text": "\"aussehen wie ein Michelin-Männchen\""}, {"kategorie": "fig.", "text": "\"aufgepumpt ausschauen\" (aufgrund der dicken Kleidung [z.B. Daunenjacke], die man anhat)"}, {"kategorie": "", "text": "überproportioniert erscheinen, aufgebläht wirken, wuchtig aussehen, wie ein [[Mehlsackl]] aussehen"}]'::jsonb, 'Dea ozwickde Blaade schaud aus wiara Mischläu-Mandal!'),
  ('dea-ozwickde-blaade-schaud-aus-wiara-mischlaeu-mandal', 'Dea ozwickde Blaade schaud aus wiara Mischläu-Mandal!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der abgezwickte Blade schaut aus wie ein Michelin-Manderl!', '[{"kategorie": "wörtlich", "text": "\"Der kurzbeinige Fettsack sieht aus wie ein Michelin-Männchen!\"  2. Der kleine Wuchtbrummer sieht echt aus wie das Michelin-Männchen!  3. Der aufgedunsene Ballon mit den kurzen Haxen sieht genauso aus wie das Michelin-Männchen!"}]'::jsonb, 'ausschaun wiara Mischläu-Mandal'),
  ('im-winta-kumm-i-ma-unta-meine-siem-schichtn-vua-wiara-mischlaeu-mandal', 'Im Winta kumm I ma unta meine siem Schichtn vua wiara Mischläu-Mandal!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Im Winter komme ich mir unter meinen sieben Schichten vor wie ein Michelin-Manderl!', '[{"kategorie": "wörtlich", "text": "\"In Winterkleidung komme ich mir unter meinen sieben Schichten vor wie ein Michelin-Männchen!\"   2. Eingepackt in all die Winterkleidung sehe ich aus wie ein Kugelmännchen!  3. Eingepackt wie ich bin, watschel ich im Winter rum wie eine aufgeblasene Speckkugel!"}]'::jsonb, ''),
  ('wea-miislsucht-hod-kriagd-a-hoochs-fiawa-und-an-ausschloog-dea-de-gaunze-haut-vabrennd', 'Wea Miislsucht hod, kriagd a hoochs Fiawa und an Ausschloog, dea de gaunze Haut vabrennd!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Wer Mieselsucht hat, kriegt hohes Fieber und einen Ausschlag, der die ganze Haut verbrennt!', '[{"kategorie": "wörtlich, medizinhistorisch", "text": "\"Die Fleckenkrankheit beginnt mit glühendem Fieber und endet in einem Ausschlag, der den ganzen Leib verbrennt!\"  2. \"Die Mieselsucht setzt mit brennendem Fieber ein und hinterlässt einen Ausschlag, der den Körper wie Feuer überzieht!\"  3. \"Bei der Ausschlagseuche kommt erst das Fieber, dann die Flecken – und am Schluss steht der ganze Leib im Brand der Krankheit!\""}]'::jsonb, ''),
  ('de-miislsuchd-hoda-im-bluad-dea-is-a-waundlnda-grantscheabm', 'De Miislsuchd hoda im Bluad - dea is a waundlnda Grantscheabm!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die Mieselsucht hat er im Blut - der ist ein wandelnder Grantscherben!', '[{"kategorie": "wörtlich", "text": "\"Die Mieselsucht steckt ihm im Blut – er ist ein wandelnder Sauertopf!\"  2. Die Mieselsucht hat er im Blut – er ist ein echter Miesepeter!  3. Der Typ ist ein Dauergriesgram - die Mieselsucht steckt in seinen Genen!"}]'::jsonb, ''),
  ('da-bua-is-miislsichdich-sei-gaunze-koeapa-brennd-und-sei-haut-schbaunnd-und-brichd-in-roode-grausliche-fleckn-aus', 'Da Bua is miislsichdich, sei gaunze Köapa brennd - und sei Haut schbaunnd und brichd in roode, grausliche Fleckn aus!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Der Bub ist mieselsüchtig, sein ganzer Körper brennt - und die Haut spannt sich und bricht in roten, wütenden Flecken aus!', '[{"kategorie": "wörtlich, medizinhistorisch", "text": "\"Der Knabe ist von der Fleckenseuche befallen: Fieber frisst sich durch seinen Körper, und der Ausschlag bricht wie Feuer aus der Haut!\"  2. \"Mieselsüchtig liegt das Kind darnieder, brennend vor Hitze, während die Haut unter dem Druck der Flecken zu bersten scheint!\"  3. \"Der Bub ist masernkrank - sein Körper glüht, und rote Flecken schlagen aus der Haut wie Brandmale!\""}]'::jsonb, ''),
  ('mid-sein-miislsichdichn-gschau-vajoogd-da-wiat-an-jeedn-gost-von-da-schaunk', 'Mid sein miislsichdichn Gschau vajoogd da Wiat an jeedn Gost von da Schaunk!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Mit seiner mieselsüchtigen Visage verjagt der Wirt jeden Gast von der Schank!', '[{"kategorie": "wörtlich", "text": "\"Mit seiner griesgrämigen Miene vertreibt der Wirt jeden Gast von der Theke!\"  2. Mit seinem missmutigen Gesichtsausdruck vertreibt der Wirt fast jeden Gast von der Schank in Richtung Gaststube!  3. Mit seiner übellaunigen Fresse verjagt der Wirt alle, die an der Schank was trinken wollen!"}]'::jsonb, ''),
  ('nooch-da-duachzechdn-nochd-woara-miislsichdich-wiara-oida-kooda', 'Nooch da duachzechdn Nochd woara miislsichdich wiara oida Kooda!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Nach der durchzechten Nacht war er mieselsüchtig wie ein alter Kater!', '[{"kategorie": "wörtlich", "text": "\"Nach der durchzechten Nacht war er kränklich wie ein alter Kater!\"  2. Nach der durchzechten Nacht lag er schlapp da wie eine ausgelutschte Zitrone!  3. Nach der durchsoffenen Nacht war er fix und fertig wie ein alter Hund!"}]'::jsonb, ''),
  ('mia1', 'mia1', '', '', '', 'Grundwortschatz Wienerisch', 'wir', '[{"kategorie": "wörtlich", "text": "\"wir\" (Personalpronomen 1. Person Plural Nominativ - betontes \"wir\" - im Gegensatz zu [[ma4]]= unbetontes \"wir\")"}, {"kategorie": "allg.", "text": "\"wir zwei\", \"wir alle\", \"wir alle zusammen\" (wird zur gezielten Hervorhebung verwendet"}]'::jsonb, 'Mia - und ned de aundan!'),
  ('mia-und-ned-de-aundan', 'Mia - und ned de aundan!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Wir – und nicht die anderen!', '[{"kategorie": "wörtlich", "text": "\"Wir – und zwar ausschließlich wir!\"  2. Wir allein – sonst niemand!  3. Wir gegen den Rest der Welt!"}]'::jsonb, ''),
  ('mia-san-mia', 'Mia san mia!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Wir sind wir!', '[{"kategorie": "wörtlich", "text": "\"Wir sind wir!\"  2. \"Wir sind heimatverbunden und etwas ganz Besonderes!\" (Ausdruck für ein Lebensgefühl, das Heimatverbundenheit und Regionalstolz repräsentieren soll)"}, {"kategorie": "fig.", "text": "\"Wir lassen uns von niemandem etwas vorschreiben!\"  4. \"Jetzt erst recht!\"  5. \"Uns kann keiner etwas anhaben!\"  6. (Fußballerjargon): \"Wir sind die Allergrößten!\" (Schlachtruf des FC Bayern München)"}]'::jsonb, ''),
  ('mia2', 'mia2', '', '', '', 'Grundwortschatz Wienerisch', 'mir', '[{"kategorie": "wörtlich", "text": "\"mir\" (Personalpronomen 1. Person Singular Dativ  - betontes \"mir\" - im Gegensatz zu [[ma1]] [=unbetontes \"mir\"])"}, {"kategorie": "allg.", "text": "\"mir\", \"mir allein\", \"ausschließlich mir\" (wird zur gezielten Hervorhebung des Sprechers [gegenüber jemand anderem] verwendet"}]'::jsonb, ''),
  ('gibs-mia-ned-eam', 'Gibs mia, ned eam!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Gib''s mir, nicht ihm!', '[{"kategorie": "wörtlich", "text": "\"Gib es mir, nicht ihm!\"  2. Mir, nicht ihm!  3. Das solltest du mir geben, nicht ihm!"}]'::jsonb, ''),
  ('des-loob-gebuead-dia-ned-eam', 'Des Loob gebüad dia, ned eam!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das Lob gebührt dir, nicht ihm!', '[{"kategorie": "wörtlich", "text": "\"Die Anerkennung steht dir zu, nicht ihm!\"  2. Die Ehre gehört dir – nicht ihm!  3. Das Lob ist ganz allein dir zuzuschreiben - nicht ihm!"}]'::jsonb, ''),
  ('waunn-i-a-viech-warad-warad-i-a-miafadl-klaa-flauschich-und-vafressn', 'Waunn I a Viech warad, warad I a Miafadl - klaa, flauschich und vafressn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn ich ein Tier wäre, wäre ich ein Meerschweinchen – klein, flauschig und verfressen!', '[{"kategorie": "wörtlich", "text": "\"Wäre ich ein Tier, dann definitiv ein Meerschweinchen – niedlich, kuschelig und ständig am Futtern!\"  2. Als Tier wäre ich ganz klar ein Meerschweinchen - klein, sanft und immer auf der Suche nach dem nächsten Leckerbissen!  3. In meiner Seele wohnt ein Meerschweinchen – sanft, kuschelbedürftig und ständig hungrig!"}]'::jsonb, ''),
  ('heast-du-klaans-miafadl-host-di-im-schlaumm-gwoeoezd-oda-wos', 'Heast, du klaans Miafadl - host di im Schlaumm gwöözd oda wos?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hör mal, du kleines Mierfadel - hast du dich im Schlamm gewälzt oder was?', '[{"kategorie": "wörtlich", "text": "\"Hey, du kleines Dreckschweinchen - hast du dich im Schlamm gewälzt oder was?\"  2. Hui, mein kleiner Dreckspatz – warst du wieder Schlammbaden?  3. Na, du kleines Schlammbärchen - bist wohl wieder kopfüber in eine Schlammpfütze gesprungen oder was?"}]'::jsonb, ''),
  ('jetzd-foada-an-sauteiraen-meazl-dea-wueue-woi-oin-zeing-dassas-gschoffd-hod', 'Jetzd foada an sauteirän Meazl - dea wüü woi oin zeing, dassas gschoffd hod!', '', '', '', 'Wiener Mechaniker-Slang', 'Jetzt fährt er einen sauteuren Merzl - der will wohl allen zeigen, dass er es geschafft hat!', '[{"kategorie": "wörtlich", "text": "\"Jetzt cruist er in ’nem fetten Mercedes durch die Gegend – der will wohl allen zeigen, dass er es geschafft hat!\"  2. Sein Mercedes sagt mehr als tausend Worte: Erfolg mit Stern!  3. Seit Kurzem fährt er einen hochpreisigen Mercedes – offenbar möchte er seinen Erfolg auch öffentlich zur Schau stellen!"}]'::jsonb, ''),
  ('hea-auf-zum-memmoeln-du-klingsd-joa-wiara-kua-beim-moeoekn', 'Hea auf zum Memmöln - du klingsd joa wiara Kua beim Möökn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Hör auf zu memmeln - du klingst ja wie ''ne Kuh beim Melken!', '[{"kategorie": "wörtlich", "text": "\"Jetzt hör mal auf mit dem Rumgeschmatze – du klingst ja wie ''ne Kuh beim Melken!\"  2. Kau doch nicht so laut – du hörst dich an wie eine wiederkäuende Kuh!  3. Mensch, schmatz nicht so – du hörst sich an, als würdest du gerade eine Pfütze leer schlürfen!"}]'::jsonb, ''),
  ('laut-offiziella-moeoedung-is-da-zugvakea-wiida-freigeem', 'Laut offiziella Möödung is da Zugvakea wiida freigeem!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Laut offizieller Meldung ist der Zugverkehr wieder freigegeben!', '[{"kategorie": "wörtlich", "text": "\"Laut einer Mitteilung der Bahn rollt der Zugverkehr wieder!\"  2. Nach offiziellen Angaben wurde der Zugverkehr wieder aufgenommen!  3. Die offizielle Stellungnahme besagt, dass der Zugverkehr wieder freigegeben ist!"}]'::jsonb, ''),
  ('moch-a-moeoedung', 'Moch a Möödung!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Mach eine Meldung!', '[{"kategorie": "wörtlich", "text": "\"So sag doch endlich was!\"  2. \"Lass uns hören!\"  3. \"Mach den Mund auf!\"  4. \"Nimm dazu Stellung!\""}]'::jsonb, ''),
  ('a-moeoedung-aussescheim', 'a Möödung aussescheim', '', '', '', 'Wiener Sprüche, die sitzen!', 'eine Meldung rausschieben', '[{"kategorie": "wörtlich", "text": "\"einen Spruch raushauen\""}, {"kategorie": "", "text": "\"eine Äußerung machen\""}, {"kategorie": "", "text": "\"ungefragt einen frechen, witzigen oder provokanten Kommentar abgeben\""}, {"kategorie": "", "text": "\"eine Ansage machen\""}]'::jsonb, 'Waunnsd noo so a Möödung aussescheibsd, fliagsd!'),
  ('waunnsd-noo-so-a-moeoedung-aussescheibsd-fliagsd', 'Waunnsd noo so a Möödung aussescheibsd, fliagsd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn du noch so eine Meldung rausschiebst, fliegst du!', '[{"kategorie": "wörtlich", "text": "\"Schieb noch einmal so ''nen Spruch raus, und du fliegst hochkant!\"  2. Noch so ’n Spruch – und du kannst deine Sachen packen!  3.  Mach noch so ’ne Ansage – und ich setz dich persönlich vor die Tür!"}]'::jsonb, 'a Möödung aussescheim'),
  ('a-moeoedung-scheim', 'a Möödung scheim', '', '', '', 'Wiener Sprüche, die sitzen!', 'eine Meldung schieben', '[{"kategorie": "wörtlich", "text": "\"einen Spruch raushauen\""}, {"kategorie": "", "text": "\"eine Äußerung machen\""}, {"kategorie": "", "text": "\"ungefragt einen witzigen oder provokanten Kommentar abgeben\""}, {"kategorie": "", "text": "\"eine Ansage machen\""}]'::jsonb, 'Dea kaunn sei Mäu ned hoidn - imma muassa iagendaa deppade Möödung scheim!'),
  ('dea-kaunn-sei-maeu-ned-hoidn-imma-muassa-iagendaa-deppade-moeoedung-scheim', 'Dea kaunn sei Mäu ned hoidn - imma muassa iagendaa deppade Möödung scheim!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der kann sein Maul nicht halten - immer muss er irgendeine depperte Meldung schieben!', '[{"kategorie": "wörtlich", "text": "\"Der hält nie die Klappe – immer muss er irgendeinen blöden Spruch ablassen!\"  2. Der kann keinen Moment ruhig sein - immer muss er ’nen dämlichen Kommentar raushauen!  3. Der kann seine Goschen einfach nicht halten - immer wieder kommt ihm ein blöder Spruch über die Lippen!"}]'::jsonb, 'a Möödung scheim'),
  ('a-mentschara-is-wiara-jaaga-rennd-seina-beute-nooch-bisas-ealeegd-hod', 'A Mentschara is wiara Jaaga - rennd seina Beute nooch, bisas ealeegd hod!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Ein Mentscherer ist wie ein Jäger - rennt seiner Beute nach, bis er sie erlegt hat!', '[{"kategorie": "wörtlich", "text": "\"Ein Schürzenjäger verfolgt seine Beute, bis er sie erlegt hat - genauso wie ein echter Jäger!\"  2. Ein Frauenheld jagt seinen Flirt, bis er sie für sich gewonnen hat – wie ein echter Jäger!  3. Ein Casanova gibt nicht auf, bis er sein Ziel erreicht – ganz wie ein Jäger im Wald!"}]'::jsonb, ''),
  ('so-a-liabs-mentschal-gaunz-de-mama', 'So a liabs Mentschal - gaunz de Mama!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'So ein liebes Mentscherl – ganz die Mama!', '[{"kategorie": "wörtlich", "text": "\"So ein liebes Mädchen – ganz die Mama!\"  2. So ein liebes Prinzesschen – ganz die Mama!  3. Was für ein kleines Engelchen – ganz die Mama!"}]'::jsonb, ''),
  ('des-mentschal-waass-genau-wiama-den-buaman-in-kopf-vadraad', 'Des Mentschal waass genau, wiama den Buaman in Kopf vadraad!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Das Mentscherl weiß genau, wie man den Buben den Kopf verdreht!', '[{"kategorie": "wörtlich", "text": "\"Das Mädchen weiß genau, wie man den Jungs den Kopf verdreht!\"  2. Das Flittchen weiß genau, wie man die Kerle um den Finger wickelt!  3. Die Göre weiß genau, wie sie die Jungs verrückt macht!"}]'::jsonb, ''),
  ('mei-oide-kochd-imma-so-an-motschka-zsaumm-den-kriagsd-nua-mit-drei-bia-owe', 'Mei Oide kochd imma so an Motschka zsaumm - den kriagsd nua mit drei Bia owe!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Meine Alte kocht immer so einen Matschker zusammen - den kriegst nur mit drei Bier runter!', '[{"kategorie": "wörtlich", "text": "\"Meine Alte kocht immer so einen Fraß zusammen - den kriegst nur mit drei Bier runter!\"  2. Wenn meine Alte wieder ihren Spezial-Matsch serviert, brauch ich drei Bier zum Runterspülen!  3. Was meine Alte da immer zusammenrührt, ist ein pappiger Einheitsbrei – runter geht’s nur mit drei Bier!"}]'::jsonb, ''),
  ('da-pfeifnraucha-klopfd-in-motschka-imma-ausse-bevuara-sei-pfeifn-neich-schdopfd', 'Da Pfeifnraucha klopfd in Motschka imma ausse, bevuara sei Pfeifn neich schdopfd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Pfeifenraucher klopft den Matschker immer raus, bevor er die Pfeife neu stopft!', '[{"kategorie": "wörtlich", "text": "\"Der Pfeifenraucher entfernt stets den Tabakrest, bevor er die Pfeife neu stopft!\"  2. Der Matsch in der Pfeife wird entfernt, ehe neuer Tabak hineinkommt!  3. Der Pfeifenraucher klopft den braunen Teerbrei raus, bevor neuer Tabak rein darf!"}]'::jsonb, ''),
  ('wos-dea-fiaran-motschka-daheareed-geed-auf-kaa-kuahaut', 'Wos dea fiaran Motschka daheareed, geed auf kaa Kuahaut!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Was der für einen Matschker daherredet, geht auf keine Kuhhaut!', '[{"kategorie": "wörtlich", "text": "\"Was der für einen Unsinn daherredet, geht auf keine Kuhhaut!\"  2. Was der für einen Schmarren zusammenredet, hält kein Mensch aus!  3. Was der für einen Schmonzes verzapft, ist nicht zum Aushalten!"}]'::jsonb, ''),
  ('jetzt-hauma-an-uandlichn-motschka-beinaund', 'Jetzt hauma an uandlichn Motschka beinaund!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Jetzt haben wir einen ordentlichen Matschker beinander!', '[{"kategorie": "wörtlich", "text": "\"Jetzt haben wir ein ordentliches Durcheinander beisammen!\"  2. Jetzt haben wir ein totales Kuddelmuddel am Hals!  3. Was wir da produziert haben, ist ein einziges Schlamassel!"}]'::jsonb, ''),
  ('waunn-mei-oida-kummd-schbritzda-ma-in-motschka-iwaroi-hii', 'Waunn mei Oida kummd, schbritzda ma in Motschka iwaroi hii!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Wenn mein Alter kommt, spritzt er mir den Matschker überall hin!', '[{"kategorie": "wörtlich", "text": "\"Wenn mein Partner kommt, spritzt er mir die Samenflüssigkeit überall hin!\"  2. Mein Alter verspritzt sein Ejakulat beim Orgasmus überallhin!  3. Wenn mein Freund kommt, saut er mich komplett mit Sperma ein!"}]'::jsonb, ''),
  ('so-a-motschkarant-schdinkd-aeaga-ois-a-tschickvaasn', 'So a Motschkarant schdinkd äaga ois a Tschickvaasn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'So ein Matschkerant stinkt ärger als ein Aschenbecher!', '[{"kategorie": "wörtlich", "text": "\"So ein Tabakkauer stinkt schlimmer als ein Aschenbecher!\"  2. So ein Tabakzuzler riecht intensiver als ein voller Aschenbecher!  3. So ein Tabaknuckler stinkt schlimmer als zehn volle Aschenbecher!"}]'::jsonb, ''),
  ('hoid-endlich-dei-goschn-du-eewicha-motschkarant-dei-sudarei-wueue-kaana-mea-hean', 'Hoid endlich dei Goschn, du eewicha Motschkarant - dei Sudarei wüü kaana mea hean!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Halt endlich deine Goschen, du ewiger Matschkerant – deine Suderei will keiner mehr hören!', '[{"kategorie": "wörtlich", "text": "\"Halt endlich dein Maul, du ständiger Grantler – dein Geraunze will keiner mehr hören!\"  2. Mach mal Pause, du Dauermeckerer – wir wissen längst, wie schlecht die Welt ist!  3. Schnauze, du Suderant – dein dauerndes Gemotze ist nicht mehr zu ertragen!"}]'::jsonb, ''),
  ('so-a-motschkara-schdinkd-aeaga-ois-a-tschickvaasn', 'So a Motschkara schdinkd äaga ois a Tschickvaasn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'So ein Matschkerer stinkt ärger als ein Aschenbecher!', '[{"kategorie": "wörtlich", "text": "\"So ein Tabakkauer stinkt schlimmer als ein Aschenbecher!\"  2. So ein Tabakzuzler riecht intensiver als ein voller Aschenbecher!  3. So ein Tabaknuckler stinkt schlimmer als zehn volle Aschenbecher!"}]'::jsonb, ''),
  ('hoid-endlich-dei-goschn-du-eewicha-motschkara-dei-sudarei-wueue-kaana-mea-hean', 'Hoid endlich dei Goschn, du eewicha Motschkara - dei Sudarei wüü kaana mea hean!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Halt endlich deine Goschen, du ewiger Matschkerer – deine Suderei will keiner mehr hören!', '[{"kategorie": "wörtlich", "text": "\"Halt endlich dein Maul, du ständiger Grantler – dein Geraunze will keiner mehr hören!\"  2. Mach mal Pause, du Dauermeckerer – wir wissen längst, wie schlecht die Welt ist!  3. Schnauze, du Suderant – dein dauerndes Gemotze ist nicht mehr zu ertragen!"}]'::jsonb, ''),
  ('so-a-masemattn-weeng-a-poa-schdingade-euro-aafoch-nua-laechalich', 'So a Masemattn weeng a poa schdingade Euro - aafoch nua lächalich!', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'So eine Masematte wegen ein paar stinkender Euros - einfach nur lächerlich!', '[{"kategorie": "wörtlich", "text": "\"So eine Schacherei wegen ein paar stinkender Euros - einfach nur lächerlich!\"  2. So ein Hin und Her wegen dem bisschen Kleingeld – einfach unfassbar!  3. So ein Gemauschel wegen ein paar lausiger Euro - absolut schwachsinnig!"}]'::jsonb, ''),
  ('a-masemattn-heem', 'a Masemattn heem', '', '', '', 'Wiener Gaunersprache', 'eine Masematten heben', '[{"kategorie": "wörtlich, Gaunersprache", "text": "\"einen Einbruchsdiebstahl begehen\""}, {"kategorie": "", "text": "\"einen Bruch machen\""}, {"kategorie": "", "text": "\"auf nächtlichen Beutezug gehen\""}]'::jsonb, 'Si haum a Masemattn ghoom, oone dass dawischd wuan san!'),
  ('si-haum-a-masemattn-ghoom-oone-dass-dawischd-wuan-san', 'Si haum a Masemattn ghoom, oone dass dawischd wuan san!', '', '', '', 'Wiener Gaunersprache', 'Sie haben eine Masematte gehoben, ohne dass sie erwischt worden sind!', '[{"kategorie": "wörtlich", "text": "\"Sie haben einen Einbruchsdiebstahl verübt, ohne erwischt worden zu sein!\"  2. Sie begingen einen Diebstahl durch Einbruch und blieben unentdeckt!  3. Sie haben die Hütte ausgeräumt und sind ungeschoren davongekommen!"}]'::jsonb, 'a Masemattn heem'),
  ('de-masemattn-is-a-soziolekt-mid-wuazln-im-roodwoeoesch-und-im-jiddischn', 'De Masemattn is a Soziolekt mid Wuazln im Roodwöösch und im Jiddischn!', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'Die Masematte ist ein Soziolekt mit Wurzeln im Rotwelsch und im Jiddischen!', '[{"kategorie": "wörtlich", "text": "\"Die Masematte ist eine Sondersprache mit Wurzeln im Rotwelsch und im Jiddischen!\"  2. Die Masematte ist eine Geheimsprache, die sich aus Rotwelsch und Jiddisch entwickelt hat!  3. Die Masematte ist eine Mischung aus Gaunersprache und Jiddisch!"}]'::jsonb, ''),
  ('mochsd-masemattn', 'Mochsd Masemattn?', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'Machst du Masematten?', '[{"kategorie": "wörtlich", "text": "\"Machst du Probleme?\"  2. Machst du Schwierigkeiten?  3. Machst du Ärger?  4. Machst du unnötige Umstände?"}]'::jsonb, ''),
  ('masemattn-san-sei-taeglichs-brood-wos-gscheids-ghackld-hod-dea-noo-nii', 'Masemattn san sei täglichs Brood - wos Gscheids ghackld hod dea noo nii!', '', '', '', 'Wiener Gaunersprache', 'Masematten sind sein täglich Brot – was G''scheites gehackelt hat der noch nie!', '[{"kategorie": "wörtlich", "text": "\"Krumme Geschäfte sind sein täglich Brot – ehrlich gearbeitet hat er nie!\"  2. Dubiose Machenschaften bestimmen sein Leben – mit ehrlicher Arbeit hatte er nie zu tun!  3. Schiebereien und dunkle Geschäfte sind sein täglich Brot – richtig gearbeitet hat er nie!"}]'::jsonb, ''),
  ('a-schuss-maggi-und-sogoa-de-toode-kua-im-suppntopf-lochd-wiida', 'A Schuss Maggi - und sogoa de toode Kua im Suppntopf lochd wiida!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ein Schuss Maggi, und selbst die tote Kuh im Suppentopf lacht wieder!', '[{"kategorie": "wörtlich", "text": "\"Ein Spritzer Maggi, und die Suppe bekommt plötzlich Leben\"  2. Maggi-Suppenwürze drauf, und die tote Sau im Topf steht fast wieder auf!  3. Maggi-Suppenwürze ist das Zauberelixier, das selbst Totes zum Leben erweckt!"}]'::jsonb, ''),
  ('de-marii-muass-schdimman', 'De Marii muass schdimman!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Die Marie muss stimmen', '[{"kategorie": "wörtlich", "text": "\"Die Kasse muss stimmen!\"  2. \"Das Geld muss passen!\"  3. [[Ohne Moos nix los!]]  4. [[Ohne Gööd ka Musi!]]"}]'::jsonb, ''),
  ('in-vueue-familien-woa-de-marii-a-klassischs-taufgeschenk', 'In vüü Familien woa de Marii a klassischs Taufgeschenk!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'In vielen Familien war die Marie ein klassisches Taufgeschenk!', '[{"kategorie": "wörtlich", "text": "\"In vielen Familien galt der Mariatheresientaler als traditionelles Geschenk zur Taufe\"  2. Der Theresientaler war über Generationen hinweg ein beliebtes Taufgeschenk!  3. Viele Kinder bekamen zur Taufe Geld in die Wiege gelegt!"}]'::jsonb, ''),
  ('da-teresientoola-wiad-seit-1741-gpraeaegd-und-is-aane-da-bekaunntastn-sueuewamuenzn-da-woeoed', 'Da Teresientoola wiad seit 1741 gpräägd und is aane da bekaunntastn Süüwamünzn da Wööd!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Der Theresientaler wird seit 1741 geprägt und ist bis heute eine der bekanntesten Silbermünzen der Welt!', '[{"kategorie": "wörtlich", "text": "\"Der Mariatheresientaler wird seit 1741 geprägt und zählt bis heute zu den berühmtesten Silbermünzen weltweit!\"  2. Seit 1741 ist der Theresientaler bereits in Umlauf und zählt auch heute noch zu den klassischen Silbermünzen!  3. Seit 1741 trägt der Theresientaler das Antlitz Maria Theresias – und bis heute Rang und Namen als berühmteste Silbermünze Österreichs!"}]'::jsonb, ''),
  ('de-wachaua-marueuen-gueued-ois-bsundas-aromatisch', 'De Wachaua Marüün güüd ois bsundas aromatisch!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Die Wachauer Marille gilt als besonders aromatisch!', '[{"kategorie": "wörtlich", "text": "\"Die Wachauer Marille ist für ihr besonders intensives Aroma bekannt!\"  2. Kenner schwören auf den einzigartigen Geschmack der Wachauer Marille!  3. Das Aroma der Wachauer Marille ist so unverwechselbar wie ihre goldene Farbe!"}]'::jsonb, ''),
  ('bist-gfaeud-in-da-marueuen', 'Bist gfäud in da Marüün?', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Bist du gefäult in der Marille?', '[{"kategorie": "wörtlich", "text": "\"Bist du faulig im Hirn?\"  2. (scherzhaft für): Bist du krank im Kopf?  3. Hast du einen [[Sprung]] in der Schüssel?"}]'::jsonb, 'gfäud in da Marüün'),
  ('gfaeud-in-da-marueuen', 'gfäud in da Marüün', '', '', '', 'Wiener Sprüche, die sitzen!', 'gefäult in der Marille', '[{"kategorie": "wörtlich", "text": "\"faulig im Kopf\""}, {"kategorie": "", "text": "krank im Kopf, nicht ganz bei Trost, geistig minderbemittelt, [[hirnmarod]], [[hirnweich]], [[hirnamputiert]]"}]'::jsonb, ''),
  ('hiinnich-in-da-marueuen-sei', 'hiinnich in da Marüün sei', '', '', '', 'Wiener Sprüche, die sitzen!', 'hinnig in der Marille sein', '[{"kategorie": "wörtlich", "text": "\"einen Hirnschaden haben\""}, {"kategorie": "", "text": "\"einen [[Sprung]] in der Schüssel haben\""}, {"kategorie": "", "text": "\"nicht ganz bei Trost sein\""}, {"kategorie": "", "text": "\"verrückt im Kopf sein\""}]'::jsonb, 'Wea mittn im Winta im See boodn geed, muass hiinnich in da Marüün sei!'),
  ('wea-mittn-im-winta-im-see-boodn-geed-muass-hiinnich-in-da-marueuen-sei', 'Wea mittn im Winta im See boodn geed, muass hiinnich in da Marüün sei!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wer mitten im Winter im See baden geht, muss hinnig in der Marille sein!', '[{"kategorie": "wörtlich", "text": "\"Wer mitten im Winter im See baden geht, muss einen Sprung in der Schüssel haben!\"  2. Wer bei Minusgraden im See baden geht, hat eindeutig einen an der Waffel!  3. Wer im Winter im See schwimmen geht, hat nicht mehr alle Tassen im Schrank!"}]'::jsonb, 'hiinnich in da Marüün sei'),
  ('an-schbrung-in-da-marueuen-haum', 'an Schbrung in da Marüün haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Sprung in der Marille haben', '[{"kategorie": "", "text": "\"einen Sprung in der Schüssel haben\""}, {"kategorie": "", "text": "\"nicht alle Tassen im Schrank haben\""}, {"kategorie": "", "text": "\"nicht ganz bei Trost sein\""}, {"kategorie": "", "text": "\"einen [[Schuss]] haben\""}, {"kategorie": "", "text": "\"nicht ganz bei Verstand sein\""}]'::jsonb, 'Wea um drei in da Nochd sei Woonung putzd, muass an Schbrung in da Schissl haum!'),
  ('wea-um-drei-in-da-nochd-sei-woonung-putzd-muass-an-schbrung-in-da-schissl-haum', 'Wea um drei in da Nochd sei Woonung putzd, muass an Schbrung in da Schissl haum!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wer um drei in der Nacht seine Wohnung putzt, muss einen Sprung in der Schüssel haben!', '[{"kategorie": "wörtlich", "text": "\"Wer nachts um drei die Wohnung putzt, muss einen Sprung in der Schüssel haben!\"  2. Wer nachts um drei die Wohnung putzt, ist wohl nicht ganz bei Verstand!  3. Wer um drei Uhr früh die Wohnung putzt, muss komplett [[gaga]] sein!"}]'::jsonb, 'an Schbrung in da Marüün haum'),
  ('soog-in-wean-nii-konfituere-schdott-mamelaad-sunst-fliagd-da-s-kipfal-glei-um-d-uan', 'Soog in Wean nii ''Konfitüre'' schdott ''Mamelaad'' - sunst fliagd da s''Kipfal glei um d''Uan!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Sag in Wien nie ''Konfitüre'' statt ''Marmelade'' - sonst fliegt dir das Kipferl gleich um die Ohren!', '[{"kategorie": "wörtlich", "text": "\"Sag in Wien nie ''Konfitüre'' statt ''Marmelade'' - sonst kriegst du das Kipferl quer in den Hals geschoben!\"  2. Sag in Wien ruhig ''Konfitüre'' – aber beschwer dich nicht, wenn dir das Kipferl dann in der Nasenwurzel landet!  3. In Wien nennt man das Marmelade – wer ''Konfitüre'' sagt, fliegt schneller aus dem Café, als er sein Kipferl retten kann!"}]'::jsonb, ''),
  ('gestan-im-kaffeehaus-haum-si-zwa-mamelaadinga-beschwead-dass-kaan-fueuetakaffee-gibd-kaunnst-da-des-vuaschdoeoen', 'Gestan im Kaffeehaus haum si zwa Mamelaadinga beschwead, dass kaan Füütakaffee gibd - kaunnst da des vuaschdöön?', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Gestern im Kaffeehaus haben sich zwei Marmeladinger beschwert, dass es keinen Filterkaffee gibt – kannst du dir das vorstellen?', '[{"kategorie": "wörtlich", "text": "\"Gestern im Kaffeehaus haben sich zwei Piefkes beschwert, dass es keinen Filterkaffee gibt – einfach unglaublich!\"  2. Da sitzen gestern zwei Norddeutsche im Café und motzen, weil kein Filterkaffee auf der Karte steht – typisch Marmeladinger!  3. Da woll’n zwei Marmeladinger in einem Wiener Kaffeehaus einen Filterkaffee – ich mein, geht''s noch?"}]'::jsonb, ''),
  ('dea-mamelaadebruada-do-drueuem-glaubd-wiakli-a-seidl-is-a-veganes-fleisch', 'Dea Mamelaadebruada do drüüm glaubd wiakli, a ''Seidl'' is a veganes Fleisch!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Marmeladebruder da drüben glaubt wirklich, ein ''Seidl'' ist veganes Fleisch!', '[{"kategorie": "wörtlich", "text": "\"Der Piefke da drüben glaubt tatsächlich, ein Seidl ist veganes Fleisch!\"  2. Der Piefkineser da drüben ist fest überzeugt, dass ein Seidl was Veganes zum Essen ist!  3. Der Norddeutsche da drüben meint ernsthaft, ''Seidl'' ist ''ne vegane Wurst!"}]'::jsonb, ''),
  ('magarinefressa-haums-zu-de-deitschn-soidoodn-im-easchdn-woeoedkriag-gsoogd-waeu-mas-mid-billiga-magarin-oogschbeisd-hod-schmoiz-oda-butta-wia-bei-uns-hods-bei-deenan-nii-geem', 'Magarinefressa haums zu de deitschn Soidoodn im easchdn Wöödkriag gsoogd, wäu mas mid billiga Magarin oogschbeisd hod - Schmoiz oda Butta wia bei uns hods bei deenan nii geem!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Margarinefresser haben sie zu den deutschen Soldaten im ersten Weltkrieg gesagt, weil man sie mit billiger Margarine abgespeist hat - Schmalz oder Butter wie bei uns hat''s bei denen nie gegeben!', '[{"kategorie": "wörtlich", "text": "\"Margarinefresser haben sie zu die deutschen Soldaten im ersten Weltkrieg genannt, weil man sie mit Billigmargarine abgespeist hat - Schmalz oder Butter wie bei uns hat''s bei denen nie gegeben!\"  2. Als Margarinefresser hat man die deutschen Soldaten im 1. Weltkrieg verspottet – denn echtes Schmalz oder Butter kannten die damals nicht!  3. Margarinefresser hat man die deutschen Soldaten genannt – mit Kunstbutter abgespeist, während wir Schmalz auf’m Brot hatten!"}]'::jsonb, ''),
  ('i-bin-heid-gaunz-marood-i-bleib-liawa-im-bett', 'I bin heid gaunz marood - I bleib liawa im Bett!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Ich bin heute ganz marod - ich bleib lieber im Bett!', '[{"kategorie": "wörtlich", "text": "\"Ich fühl mich heute ganz kränklich - ich bleib lieber im Bett!\"  2. Mir geht’s heute gar nicht gut, drum bleib ich lieber im Bett!  3. Ich bin heute total unpässlich - besser, ich bleib im Bett!"}]'::jsonb, ''),
  ('so-marood-wia-de-fiama-beinaund-is-daeda-i-kaan-cent-dafia-zoin', 'So marood wia de Fiama beinaund is, däda I kaan Cent dafia zoin!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'So marod wie die Firma beisammen ist, tät ich keinen Cent dafür bezahlen!', '[{"kategorie": "wörtlich", "text": "\"So angeschlagen wie die Firma dasteht, würde ich keinen Cent investieren!\"  2. Die Firma ist derart abgewirtschaftet, da würd ich keinen Cent dafür bezahlen!  3. So sanierungsbedürftig wie das Unternehmen ist, wär es mir keinen Cent wert!"}]'::jsonb, ''),
  ('dea-schaud-so-marooni-aus-ois-haedns-eam-iwad-nochd-im-koella-eigschbead', 'Dea schaud so marooni aus, ois hädns eam iwad Nochd im Kölla eigschbead!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der schaut so maroni aus, als hätten sie ihn über Nacht im Keller eingesperrt!', '[{"kategorie": "wörtlich", "text": "\"Der sieht so marode aus, als hätten sie ihn über Nacht im Keller eingesperrt!\"  2. Der sieht so angeschlagen aus, als hätte er die ganze Nacht im Keller verbracht!  3. Der sieht so kränklich aus, als wäre er eine Nacht lang im Keller eingesperrt gewesen!"}]'::jsonb, ''),
  ('von-dem-kriagsd-kaan-cent-seitn-ualaub-isa-voi-marooni', 'Von dem kriagsd kaan Cent - seitn Ualaub isa voi marooni!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Von dem bekommst du keinen Cent - seit dem Urlaub ist er voll maroni!', '[{"kategorie": "wörtlich", "text": "\"Von dem bekommst du keinen Cent - seit dem Urlaub ist er komplett marode!\"  2. Von dem siehst du kein Geld – seit dem Urlaub ist er total pleite!  3. Der gibt dir keinen Cent – seit dem Urlaub ist er schlichtweg bankrott!"}]'::jsonb, ''),
  ('in-fraunkreich-mochd-ma-ausd-marooni-sogoar-a-bia', 'In Fraunkreich mochd ma ausd Marooni sogoar a Bia!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'In Frankreich macht man aus den maroni sogar ein Bier!', '[{"kategorie": "wörtlich", "text": "\"In Frankreich verarbeitet man Maronen sogar zu Bier!\"  2. Aus Esskastanien wird in Frankreich sogar Bier gemacht!  3. In Frankreich dient die Edelkastanie sogar als Grundlage für Bier!"}]'::jsonb, ''),
  ('da-maroonibrooda-ghead-in-wean-zum-schdodtbueued-wia-de-fiaka-und-de-oidn-gaaslateanen', 'Da Maroonibrooda ghead in Wean zum Schdodtbüüd wia de Fiaka und de oidn Gaaslateanen!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Der Maronibrater gehört in Wien zum Stadtbild wie die Fiaker und die alten Gaslaternen!', '[{"kategorie": "wörtlich", "text": "Die Kastanienbrater prägen das Stadtbild Wiens genauso wie die Fiakern und die alten Gaslaternen!  2. Maronibrater, Fiaker und Gaslaternen – sie alle tragen den Geist des alten Wien in die Gegenwart!  3. Maronibrater sind für Wien genauso wie die alten Fiaker und Gaslaternen ein Stück Seele der Stadt!"}]'::jsonb, ''),
  ('aum-grisskindlmoakd-deaf-da-kesdnbrooda-ned-foeoen', 'Aum Grisskindlmoakd deaf da Kesdnbrooda ned föön!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Am Christkindlmarkt darf der Kestenbrater nicht fehlen!', '[{"kategorie": "wörtlich", "text": "\"Kein Wiener Christkindlmarkt ist komplett ohne einen Kastanienbrater!\"  2. Am Christkindlmarkt braucht’s unbedingt den Maronimann!  3. In Wien ist der Maronibrater fixer Bestandteil des Christkindlmarktes!"}]'::jsonb, 'Wiiner Grisskindlmoakt'),
  ('da-maroonioofn-is-im-winta-genauso-wichtig-wias-punschschdandl', 'Da Maroonioofn is im Winta genauso wichtig wias Punschschdandl!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Der Maroniofen ist im Winter genauso wichtig wie das Punschstandl!', '[{"kategorie": "wörtlich", "text": "\"Der Kastanienofen ist im Winter so unverzichtbar wie der Punschstand!\"  2. Zum Winterbild in Wien gehören Maroniöfen genauso wie Punsch- und Glühweinstände!  3. In Wien ist der heiße Maroniofen im Winter genauso Tradition wie der Punschstand!"}]'::jsonb, ''),
  ('im-winta-waeamd-a-becha-punsch-bessa-ois-jeeda-mauntl', 'Im Winta wäamd a Becha Punsch bessa ois jeeda Mauntl!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Im Winter wärmt ein Becher Punsch besser als jeder Mantel!', '[{"kategorie": "wörtlich", "text": "\"An kalten Tagen wärmt ein heißer Punsch besser als jede Winterkleidung!\"  2. Ein Häferl Punsch wärmt im Winter besser als drei Decken und ''ne Wärmflasche!  3. Kein Mantel kann, was ein g’scheiter Punsch schafft!"}]'::jsonb, ''),
  ('da-schnoeoesde-weg-vom-grisskindlmoakd-ind-fettn-fiad-iwas-punschschdandl', 'Da schnöösde Weg vom Grisskindlmoakd ind Fettn fiad iwas Punschschdandl!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der schnellste Weg vom Christkindlmarkt in die Fetten führt über den Punschstand!', '[{"kategorie": "wörtlich", "text": "\"Der schnellste Weg vom Christkindlmarkt in den Rausch führt über den Punschstand!\"  2. Am Christkindlmarkt kommst übers Punschstandl am schnellsten ins Delirium!  3. Keine Bar ist so gefährlich wie ein Punschstand!"}]'::jsonb, ''),
  ('des-maschal-is-es-marknzeichn-von-de-koeoena-in-an-klassischn-wiina-kaffeehaus', 'Des Maschal is es Marknzeichn von de Kööna in an klassischn Wiina Kaffeehaus!', '', '', '', 'Wiener Kaffeehaus-ABC', 'Das Mascherl ist das Markenzeichen der Kellner in einem klassischen Wiener Kaffeehaus!', '[{"kategorie": "wörtlich", "text": "\"Die Fliege ist das Markenzeichen der Kellner im Wiener Kaffeehaus!\"  2. Das Querbinderl gilt als typisches Kennzeichen der Wiener Kaffeehauskellner!  3. Die Bindeschleife ist fester Bestandteil der Kellneruniform im Wiener Kaffeehaus!"}]'::jsonb, ''),
  ('min-rosa-maschal-im-hoa-schaud-de-klaane-aus-wiara-geschenkpackal', 'Min rosa Maschal im Hoa schaud de Klaane aus wiara Geschenkpackal!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Mit dem rosa Mascherl im Haar sieht die Kleine aus wie ein Geschenkpackerl!', '[{"kategorie": "wörtlich", "text": "\"Mit der pinken Schleife im Haar sieht die Kleine aus wie ein Geschenkpäckchen!\"  2. Mit dem rosa Haarband wirkt die Kleine wie ein Geschenkpaket!  3. Mit der rosafarbenen Masche im Haar sieht die Kleine aus wie ein hübsch verpacktes Geschenk!"}]'::jsonb, ''),
  ('a-maschal-im-glaasal-a-zigarral-im-fotz-so-hod-da-heagood-in-feiaoobnd-fia-mi-gmochd', 'A Maschal im Glaasal, a Zigarral im Fotz - so hod da Heagood in Feiaoobnd fia mi gmochd!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ein Mascherl im Glaserl, ein Zigarrerl im Fotz – so hat der Herrgott den Feierabend für mich gemacht!', '[{"kategorie": "wörtlich", "text": "\"Weinbrand-Orange im Gläschen und ein Zigarrchen im Mund – so hat der Herrgott den Feierabend für mich gemacht!\"  2. Weinbrand-Orange im Gläschen und eine kleine Zigarre zwischen den Lippen – das ist Feierabend pur für mich!  3. Ein Orangenbrand im Glas und ein Stumpen im Mund – so hat der Herrgott den Feierabend für mich erdacht!"}]'::jsonb, ''),
  ('kaa-maschal-haum', 'kaa Maschal haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'kein Mascherl haben', '[{"kategorie": "wörtlich", "text": "\"keine Schleife tragen\""}, {"kategorie": "fig.", "text": "\"keine äußere Herkunftskennzeichnung aufweisen\""}, {"kategorie": "", "text": "\"nicht mit einer bestimmten Etikette behaftet sein\""}]'::jsonb, 'Gööd hod kaa Maschal!'),
  ('goeoed-hod-kaa-maschal', 'Gööd hod kaa Maschal!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Geld hat keim Mascherl!', '[{"kategorie": "wörtlich", "text": "\"Geld trägt keine Schleife!\"  2. Geld weist keinerlei Herkunftsbezeichnung auf!  3. Geld trägt keinerlei Etikette!  4. Beim Geld spielt es keine Rolle, woher es kommt!"}]'::jsonb, ''),
  ('es-rennd-ollas-wiar-aum-maschal', 'Es rennd ollas wiar aum Maschal!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Es rennt alles wie am Mascherl!', '[{"kategorie": "wörtlich", "text": "\"Es läuft alles wie am Schnürchen!\"  2. \"Alles läuft wie geschmiert!\"  3.  \"Alles läuft wie auf Schienen!\""}]'::jsonb, ''),
  ('da-wueuede-mit-seina-maschin', 'Da Wüüde mit seina Maschin', '', '', '', 'Wiener Mechaniker-Slang', 'Der Wilde mit seiner Maschin', '[{"kategorie": "wörtlich", "text": "\"Der Wilde mit seiner Maschine\" (Titel eines Wiener Couplets von Gerhard Bronner, gesungen von Helmut Qualtinger)"}, {"kategorie": "", "text": "\"Der Wilde mit seinem Feuerstuhl!\"  3. \"Der Ungezähmte auf seinem heißen Ofen!\""}]'::jsonb, 'Bis jetzt woar I in unsara Plottn da Gfüüde, jetzt wissens olle in mia schdeckt no was drinn'', in meina Gossn nennt mi jeeda jetzt ''da Wüüde mit seina Maschin!'''),
  ('bis-jetzt-woar-i-in-unsara-plottn-da-gfueuede-jetzt-wissens-olle-in-mia-schdeckt-no-was-drinn-in-meina-gossn-nennt-mi-jeeda-jetzt-da-wueuede-mit-seina-maschin', 'Bis jetzt woar I in unsara Plottn da Gfüüde, jetzt wissens olle in mia schdeckt no was drinn'', in meina Gossn nennt mi jeeda jetzt ''da Wüüde mit seina Maschin!''', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Bis jetzt war ich in unserer Platten der G''füllte, doch jetzt wissen sie alle, in mir steckt was drin - in meiner Gassen nennt mich jeder jetzt ''der Wilde mit seiner Maschin''!', '[{"kategorie": "wörtlich", "text": "\"Bis jetzt war ich in unserem Plattenbau der Dicke, doch jetzt wissen sie alle, in mir steckt was drin - in meiner Gasse nennt mich jeder jetzt ''der Wilde mit seiner Maschin''!\" (Text des Wiener Couplets ''der Halbwilde'' von Gerhard Bronner, gesungen von Helmut Qualtinger)"}, {"kategorie": "", "text": "Vorher war ich im Plattenbau nur ''der Dicke'' – heute nennen sie mich den ''Ungezähmten auf seinem heißen Ofen''!  3. In unserem Viertel war ich früher bloß ''der Dicke'' – jetzt bin ich ''der Wilde mit seinem Donnerross''!"}]'::jsonb, ''),
  ('im-heaz-von-dem-flitza-sitzd-a-ochtzilindrische-maschin', 'Im Heaz von dem Flitza sitzd a ochtzilindrische Maschin!', '', '', '', 'Wiener Mechaniker-Slang', 'Im Herz von diesem Flitzer sitzt eine achtzylindrische Maschine!', '[{"kategorie": "wörtlich", "text": "\"Das Herzstück dieses Flitzers ist ein Achtzylinder-Motor!\"  2. Im Herz dieses Boliden steckt ein Achtzylinder-Block!  3. Die Seele des Wagens ist sein Achtzylinder-Donnerwerk!"}]'::jsonb, ''),
  ('waunn-dea-maaslscheiwa-in-misthaufn-foid-kummda-mid-goidschdaub-ind-hoa-wiida-ausse', 'Waunn dea Maaslscheiwa in Misthaufn foid, kummda mid Goidschdaub ind Hoa wiida ausse!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn dieser Maselschieber in ''nen Misthaufen fällt, kommt er mit Goldstaub in den Haaren wieder raus!', '[{"kategorie": "wörtlich", "text": "\"Wenn diese Glückssau in ''nen Misthaufen fällt, kommt er mit Goldstaub in den Haaren wieder raus!\"  2. Dieser Glückspilz könnte in die Scheiße greifen – und würde trotzdem ''n Lottoschein finden!  3. Fällt dieses Glückskind in den Gulli, kommt er mit ''nem Goldfisch und ’ner Rolex wieder raus!"}]'::jsonb, ''),
  ('dea-typ-is-ka-untaneema-des-is-a-maaslritta-mid-teire-schuach-und-leere-vaschbrechn', 'Dea Typ is ka Untaneema - des is a Maaslritta mid teire Schuach und leere Vaschbrechn!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der Typ ist kein Unternehmer – das ist ein Maselritter mit teuren Schuhen und leeren Versprechen!', '[{"kategorie": "wörtlich", "text": "\"Der Typ ist kein Unternehmer – das ist ein Glücksritter mit teuren Schuhen und leeren Versprechen!\"  2. Der Typ ist kein echter Unternehmer, eher ein Schaumschläger mit Luxusschuhen und großem Maul!  3. Das ist kein Unternehmer – das ist ein Start-up-Cowboy mit leeren Taschen und großen Sprüchen!"}]'::jsonb, ''),
  ('dea-maaslitika-hod-scho-wiida-im-lotto-gwunna', 'Dea Maaslitika hod scho wiida im Lotto gwunna!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Maslitiker hat schon wieder im Lotto gewonnen!', '[{"kategorie": "wörtlich", "text": "\"Dieser chronisch vom Glück Verfolgte hat schon wieder im Lotto gewonnen!\"  2. Das Schicksal scheint diesem Glückspilz auf ewig gewogen – er hat schon wieder im Lotto gewonnen!  3. Der Typ ist ein vom Glück geküsster Lebenskünstler - schon wieder hat er im Lotto abgesahnt!"}]'::jsonb, ''),
  ('a-maasl-haum', 'a Maasl haum', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'ein Masel haben', '[{"kategorie": "wörtlich", "text": "\"Glück haben\" (eigtl. \"unter einem Glücksstern stehen\", vom hebräischen \"masel\"=\"Glücksstern\")"}, {"kategorie": "allg.", "text": "im Glück sein"}, {"kategorie": "", "text": "das Glück auf seiner Seite haben"}]'::jsonb, 'Ned nua Hackln zööd - im Leebm muassd aa a Maasl haum!'),
  ('a-maasn-haum', 'a Maasn haum', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'eine Masen haben', '[{"kategorie": "wörtlich", "text": "\"Glück haben\" (eigtl. \"unter einem Glücksstern stehen\", vom hebräischen \"masel\"=\"Glücksstern\", stilistische Variante von [[Masel]], in Anlehnung an \"Meise\")"}, {"kategorie": "", "text": "\"im Glück sein\""}, {"kategorie": "", "text": "\"das Glück auf seiner Seite haben\""}]'::jsonb, ''),
  ('maasl-ghobd', 'Maasl ghobd!', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'Masel gehabt!', '[{"kategorie": "wörtlich", "text": "\"Glück gehabt!\"  2. \"Nochmal gut gegangen!\"  3. \"Schwein gehabt!\""}]'::jsonb, ''),
  ('ned-nua-hackln-zoeoed-im-leebm-muassd-aa-a-maasl-haum', 'Ned nua Hackln zööd - im Leebm muassd aa a Maasl haum!', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'Nicht nur Hackeln zählt - im Leben musst auch ein Masel haben!', '[{"kategorie": "wörtlich", "text": "\"Nicht nur Arbeit zählt - im Leben musst du auch ein bisschen Glück haben!\"  2. Fleiß ist wichtig – aber man braucht auch ein Quäntchen Glück im Leben!  3. Nicht jeder Schweiß tropft in Gold – manchmal braucht es auch den Kuss der Fortuna!"}]'::jsonb, 'a Maasl haum'),
  ('waunn-ana-a-maasn-hod-koibd-a-sei-ochs', 'Waunn ana a Maasn hod, koibd a sei Ochs!', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'Wenn einer eine Masen hat, kalbt auch sein Ochs''!', '[{"kategorie": "wörtlich", "text": "\"Wenn jemand eine Glückssträhne hart, kalbt sogar sein Ochse!\"  2. Wenn du das Glück auf deiner Seite hast, kalbt dir sogar dein Ochse!  3. Läuft das Glück, klappt alles – sogar Dinge, die eigentlich gar nicht klappen können!"}]'::jsonb, 'a Maasn haum'),
  ('hea-auf-zum-mauschln-reed-deitlich', 'Hea auf zum Mauschln - reed deitlich!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Hör auf zu mauscheln - rede deutlich!', '[{"kategorie": "wörtlich", "text": "\"Hör auf zu mauscheln - sprich deutlich!\"  2. Bitte deutlich sprechen, ich versteh kein Wort!  3. Murmel nicht in deinen Bart hinein - red lauter und klarer!"}]'::jsonb, ''),
  ('waunn-mei-oide-mid-iara-freindin-zum-mauschln-aufaungd-daunn-wiad-s-gfaealich', 'Waunn mei Oide mid iara Freindin zum Mauschln aufaungd, daunn wiad''s gfäalich!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Wenn meine Alte mit ihrer Freundin zu mauscheln beginnt, dann wird''s gefährlich!', '[{"kategorie": "wörtlich", "text": "\"\"Wenn meine Alte mit ihrer Freundin zu tuscheln anfängt, dann wird''s gefährlich!\"  2. Wenn meine Frau mit ihrer besten Freundin zu tuscheln anfängt, weiß ich: Das wird teuer oder peinlich!  3. Wenn die beste Freundin meiner Frau auftaucht und die beiden zu flüstern beginnen wie Hexen um den Kessel, dann wird’s für mich finster!"}]'::jsonb, ''),
  ('nau-wos-wiad-do-wiida-gmauschld-de-groosse-woeoedvaschwoerung', 'Nau, wos wiad do wiida gmauschld - de groosse Wöödvaschwörung?', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Na, was wird da wieder gemauschelt? Die große Weltverschwörung?', '[{"kategorie": "wörtlich", "text": "\"Na, worüber wird denn da schon wieder heimlich getuschelt? Die große Weltverschwörung?\"  2. Mensch, was wird denn da gemauschelt? Verschwört ihr euch gegen mich oder die ganze Menschheit?  3. Wird da wieder hinterrücks intrigiert oder ist es reiner Zufall, dass ihr die Köpfe zusammensteckt und heimlich flüstert?"}]'::jsonb, ''),
  ('bei-dem-mauschla-brauchsd-untatitl-dea-reed-ois-haeda-an-kautschi-in-da-goschn', 'Bei dem Mauschla brauchsd Untatitl - dea reed, ois häda an Kautschi in da Goschn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Bei diesem Mauschler brauchst du Untertitel - der redet, als hätte er einen Kautschi in der Goschen!', '[{"kategorie": "wörtlich", "text": "\"Bei diesem Nuschler brauchst du Untertitel - der redet, als hätte er einen Kaugummi im Mund!\"  2. Bei diesem Wortverschlucker brauchst du ''ne Simultanübersetzung  – der nuschelt sich durch jeden Satz, ohne Pause, ohne Punkt!  3. Dieser Brabbler spricht so unverständlich, als hätte er einen Knödel im Mund!"}]'::jsonb, ''),
  ('wea-de-mauschla-kennd-waass-aus-woecha-richtung-da-wind-waad', 'Wea de Mauschla kennd, waass, aus wöcha Richtung da Wind waad!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wer die Mauschler kennt, weiß, aus welcher Richtung der Wind weht!', '[{"kategorie": "wörtlich", "text": "\"Wer die Strippenzieher kennt, weiß auch, aus welcher Richtung der Wind weht!\"  2. Wenn du weißt, wer die echten Entscheider sind, siehst du kommen, was passiert!  3. Wer die Spielmacher kennt, durchschaut das Spiel!"}]'::jsonb, ''),
  ('i-vaschdee-kaa-wuat-von-eichara-mauschlarei-reeds-deitlich', 'I vaschdee kaa Wuat von eichara Mauschlarei - reeds deitlich!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich verstehe kein Wort von eurer Mauschlerei - redet deutlich!', '[{"kategorie": "wörtlich", "text": "\"Ich verstehe kein Wort von eurem Gemurmel - redet deutlich!\"  2. Ich verstehe kein Wort von eurem Genuschel – sprecht bitte klar und deutlich!  3. Was soll diese Flüsterei? Sprecht, dass man euch versteht!"}]'::jsonb, ''),
  ('de-mauschlarei-in-da-politik-geed-ma-gsund-aum-zaaga-lauta-gschaftlhuawa-und-daumpfplaudara', 'De Mauschlarei in da Politik geed ma gsund aum Zaaga - lauta Gschaftlhuawa und Daumpfplaudara!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die Mauschlerei in der Politik geht mir gsund auf den Zeiger - lauter Gschaftlhuber und Dampfplauderer!', '[{"kategorie": "wörtlich", "text": "\"Das Gemauschel in der Politik hängt mir zum Hals raus – lauter Schaumschläger und Phrasendrescher!\"  2. Die ewige Strippenzieherei in der Politik kotzt mich an – alles nur heiße Luft und Schaumschlägerei!  3. Die Hinterzimmerpolitik geht mir mächtig auf den Keks – ein Haufen Schwätzer und Maulhelden!"}]'::jsonb, ''),
  ('aun-da-schaunk-woa-friara-des-greisch-von-da-motschkarei-oigeegnwaeatich-wia-da-geruch-von-rauch-und-bia', 'Aun da Schaunk woa friara des Greisch von da Motschkarei oigeegnwäatich -wia da Geruch von Rauch und Bia!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'An der Schank war früher das Geräusch der Matschkerei allgegenwärtig - wie der Geruch von Rauch und Bier!', '[{"kategorie": "wörtlich", "text": "\"An der Wirtshaustheke war einst das Geräusch der Matschkerei ebenso allgegenwärtig wie der Geruch von Rauch und Bier!\"  2. \"An der Schankwar einst das stete Kauen des Tabaks ebenso präsent wie Rauchschwaden und Bierdunst!\"  3. \"An der Theke war einst das Geräusch der Tabakmatscherei so selbstverständlich wie der Duft von Rauch und frischem Bier!\""}]'::jsonb, ''),
  ('kaunnst-mit-dera-motschkarei-bitte-aufhean-ma-head-di-bis-aum-gaung-ausse-fressn', 'Kaunnst mit dera Motschkarei bitte aufhean? Ma head di bis aum Gaung ausse fressn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Kannst du mit dieser Matschkerei bitte aufhören? Man hört dich bis auf den Gang hinaus fressen!', '[{"kategorie": "wörtlich", "text": "\"Könntest du bitte etwas leiser essen? Man hört dich bis auf den Gang hinaus schmatzen!\"  2. Iss bitte ein bisschen gesitteter – man hört dich bis vor die Tür hinaus mampfen!  3. Hör auf mit dieser unappetitlichen Schmatzerei - du mampfst ja wie eine wiederkäuende Kuh!"}]'::jsonb, ''),
  ('dera-ia-schdaendige-motschkarei-geed-ma-uandlich-aum-zaaga', 'Dera ia schdändige Motschkarei geed ma uandlich aum Zaaga!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die ständige Matschkerei von ihr geht mir ordentlich auf den Zeiger!', '[{"kategorie": "wörtlich", "text": "\"Ihr ständiges Gemotze geht mir sowas von am Geist!\"  2. Ihre ständige Suderei geht mir echt am Nerv!  3. Bei dem dauernden Gemecker krieg ich Ohrenbluten – wann hört die endlich auf?"}]'::jsonb, ''),
  ('ned-amoi-beim-reedn-head-a-auf-zum-motschkan', 'Ned amoi beim Reedn head a auf zum Motschkan!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Nicht einmal beim Reden hört er auf zu matschkern!', '[{"kategorie": "wörtlich, hist.", "text": "\"Nicht einmal beim Sprechen hört er auf, den Tabak weiterzukauen!\"  2. \"Nicht einmal beim Reden nimmt er den Kautabak aus dem Mund!\"  3. \"Er redet und kaut gleichzeitig, als gäbe es keinen Unterschied!\""}]'::jsonb, ''),
  ('motschka-ned', 'Motschka ned!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Matschker nicht!', '[{"kategorie": "wörtlich", "text": "\"Nörgle nicht rum!\"  2. \"Hör auf zu meckern!\"  3. \"Lass das Geraunze!\"  4. \"Motz nicht rum!\""}]'::jsonb, ''),
  ('motschka-ned-weng-jeedn-schaas', 'Motschka ned weng jeedn Schaas!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Matschker nicht wegen jedem Schas!', '[{"kategorie": "wörtlich", "text": "\"Nörgle nicht wegen jeder Kleinigkeit rum!\"  2. \"Hör auf, wegen jedem Schmarren  zu meckern!\"  3. \"Lass das Geraunze wegen nichts und wieder nichts!\"  4. \"Motz nicht wegen jedem Furz rum!\""}]'::jsonb, ''),
  ('dea-motschkad-aun-seina-leewakaassemmae-umanaund-wiara-sau-im-troog', 'Dea motschkad aun seina Leewakaassemmä umanaund wiara Sau im Troog!', '', '', '', 'Wiener Würstelstandjargon', 'Der matschkert an seiner Leberkässemmel rum wie ''ne Sau im Trog!', '[{"kategorie": "wörtlich", "text": "\"Der schmatzt an seiner Leberkässemmel rum wie ''ne Sau im Futtertrog!\"  2. Der mampft seine Leberkässemmel wie eine wiederkäuende Kuh!  3. Der nuckelt an seiner Leberkässemmel wie ein Ochse beim Wiederkäuen, nur lauter!"}]'::jsonb, ''),
  ('dea-motschkad-wiara-oida-gaassbock-waunns-ned-nooch-sein-schaedl-rennd', 'Dea motschkad wiara oida Gaassbock, waunns ned nooch sein Schädl rennd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der matschkert wie ein alter Geißbock, wenn’s nicht nach seinem Schädel rennt!', '[{"kategorie": "wörtlich", "text": "\"Der motzt wie ein alter Ziegenbock, wenn’s nicht nach seinem Kopf geht!\"  2. Der nörgelt wie ein alter Rentner, wenn’s nicht so läuft, wie er will!  3. Der meckert bei jeder Kleinigkeit, wenn er nicht kriegt, was er will!"}]'::jsonb, ''),
  ('tua-mi-ned-in-aana-tua-aumotschkan-i-kaunn-nix-dafia', 'Tua mi ned in aana Tua aumotschkan - I kaunn nix dafia!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Tu mich nicht in einer Tour anmatschkern - ich kann nichts dafür!', '[{"kategorie": "wörtlich", "text": "\"Motz mich nicht ständig an – ich kann nichts dafür!\"  2. Nörgle nicht ständig an mir rum – ich hab nichts damit zu tun!  3. Erspar mir dein ständiges Gemeckere - ich bin sicher nicht der Schuldige!"}]'::jsonb, ''),
  ('du-host-de-banaan-komplett-zamotschkad-de-kauma-nimma-essn', 'Du host de Banaan komplett zamotschkad - de kauma nimma essn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Du hast die Banane komplett zermatschkert – die kann man nimmer essen!', '[{"kategorie": "wörtlich", "text": "\"Du hast die Banane komplett zerdrückt – die kann man nicht mehr essen!\"  2. Du hast die Banane total zerquetscht – so kann man die leider nicht mehr essen!  3. Du hast die Banane ja total zermatscht – die ist doch nur noch Brei!"}]'::jsonb, ''),
  ('wos-de-oide-in-gaunz-toog-zsaummmotschkad-geed-auf-kaa-kuahaut-mea', 'Wos de Oide in gaunz Toog zsaummmotschkad, geed auf kaa Kuahaut mea!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Was die Alte den ganzen Tag zusammenmatschkert, geht auf keine Kuhhaut mehr!', '[{"kategorie": "wörtlich", "text": "\"Was die Alte den ganzen Tag zusammenmotzt, ist nicht mehr auszuhalten!\"  2. Was die Alte da ständig vom Stapel lässt, bringt einen noch um den Verstand!  3. Das ständige Gemeckere dieser Frau geht wirklich auf keine Kuhhaut mehr!"}]'::jsonb, ''),
  ('dea-motschkad-ollas-zsaumm-wiara-sau-im-troog', 'Dea motschkad ollas zsaumm wiara Sau im Troog!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der matschkert alles zusammen wie ''ne Sau im Trog!', '[{"kategorie": "wörtlich", "text": "\"Der mampft alles auf wie eine Sau am Trog!\"  2. Der frisst alles zusammen auf wie ein Tier im Stall!  3. Der schmatzt alles auf wie ein Schwein am Trog!"}]'::jsonb, ''),
  ('klaane-matura', 'klaane Matura', 'die', '', '', 'Grundwortschatz Wienerisch', 'kleine Matura', '[{"kategorie": "wörtlich", "text": "\"kleine Matura\" (vom lateinischen \"examina matura\"=\"Reifeprüfung\")"}, {"kategorie": "allg.", "text": "\"Sekundarschulabschluss-Light\", \"Matura für Arme\", \"Billigmatura\", \"Matura im Schmalspurformat\" (Die „kleine Matura“ war eine in Österreich bis in die 1960er-Jahre gebräuchliche Bezeichnung für einen abgeschwächten Schulabschluss, der im Vergleich zur „großen Matura“ [der regulären Reifeprüfung an Gymnasien oder höheren Schulen] weniger anspruchsvoll war. Die kleine Matura berechtigte nicht zum Universitätsstudium, sondern eher zu praktischen Berufen oder weiterführenden Fachausbildungen)"}]'::jsonb, 'Dea hod nua de klaane Matura - via Joa Voiksschui und zwa Taunzstundn!'),
  ('a-maeubal-noch-da-aundan-haazn', 'a Mäubal noch da aundan haazn', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein Mäuberl nach der anderen heizen', '[{"kategorie": "wörtlich", "text": "\"ein Marlboro-Zigarettchen nach der anderen rauchen\""}, {"kategorie": "", "text": "\"Zigarette um Zigarette rauchen\""}, {"kategorie": "", "text": "\"Marlboro rauchen wie ein Ofenrohr\""}]'::jsonb, ''),
  ('nooch-da-valaengarung-und-in-oeoefaschiassn-woar-i-richtig-im-oasch-komplett-maukas', 'Nooch da Valängarung und in Ööfaschiassn woar I richtig im Oasch – komplett maukas!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Nach der Verlängerung und dem Elferschießen war ich richtig im Arsch - komplett maukas!', '[{"kategorie": "wörtlich", "text": "\"Nach der Verlängerung und dem Elferschießen war ich richtig im Arsch - komplett erledigt!\"  2. \"Nach der Verlängerung und dem Elferschießen war ich fix und fertig - komplett hinüber!\"  3. \"Nach der Verlängerung und dem Elferschießen war ich stehend k. o. – ausgelaugt wie ein leerer Akku!\""}]'::jsonb, ''),
  ('de-wuaschd-is-scho-gaunz-maukas', 'De Wuaschd is scho gaunz maukas!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Die Wurst ist schon ganz maukas!', '[{"kategorie": "wörtlich", "text": "\"Die Wurst ist schon ganz verdorben!\"  2. \"Die Wurst ist nicht mehr genießbar!\"  3. \"Die Wurst ist hinüber!\""}]'::jsonb, ''),
  ('maukas-gee', 'maukas gee', '', '', '', 'Tod und Sterben auf Wienerisch', 'maukas gehen', '[{"kategorie": "wörtlich", "text": "\"vor die Hunde gehen\" (vom jiddischen \"machuk\"=\"ausgelöscht\")"}, {"kategorie": "allg.", "text": "sterben, das Zeitliche segnen, [[die]] Patschen strecken, [[den]] Löffel abgeben, [[ein]] Bankerl reißen, [[die]] Eisen aufstellen, [[in]] Deifä sei easchda Haaza wean"}]'::jsonb, 'Iagendwaunn gee ma olle maukas - oiso sauf ma, solaung ma no kenna!'),
  ('iagendwaunn-gee-ma-olle-maukas-oiso-sauf-ma-solaung-ma-no-kenna', 'Iagendwaunn gee ma olle maukas - oiso sauf ma, solaung ma no kenna!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Irgendwann gehen wir alle maukas - also saufen wir, solange wir noch können!', '[{"kategorie": "wörtlich", "text": "\"Irgendwann gehen wir alle vor die Hunde - also saufen wir, solange wir noch können!\"  2. Irgendwann müssen wir alle sterben – also trinken wir, solange es noch geht!  3. Früher oder später beißt jeder ins Gras – also saufen wir, solange wir noch leben!"}]'::jsonb, 'maukas gee'),
  ('wem-maukas-mochn', 'wem maukas mochn', '', '', '', 'Wiener Gaunersprache', 'jemanden maukas machen', '[{"kategorie": "wörtlich", "text": "\"jemanden tot machen\" (vom jiddischen \"machuk\"=\"ausgelöscht\")"}, {"kategorie": "Gaunerjargon", "text": "jemanden kaltmachen, umbringen, ins Jenseits befördern, [[abkrageln]], [[abmaxeln]], [[heimdrehen]]"}]'::jsonb, 'Dea hod zvüü greedt, drum haums eam maukas gmochd!'),
  ('dea-hod-zvueue-greedt-drum-haums-eam-maukas-gmochd', 'Dea hod zvüü greedt, drum haums eam maukas gmochd!', '', '', '', 'Wiener Gaunersprache', 'Der hat zu viel geredet - darum haben sie ihn maukas gemacht!', '[{"kategorie": "wörtlich", "text": "\"Der hat zu viel geredet - darum haben sie ihn kaltgemacht!\"  2. Der hat den Mund zu weit aufgemacht - darum haben sie ihn umgelegt!  3. Der hat gesungen wie ein Kanari - darum haben sie ihn zum Schweigen gebracht!"}]'::jsonb, 'wem maukas mochn'),
  ('mit-deina-aubergine-kaunnst-di-glei-schleichn-bei-uns-gibds-melanzani-oida-melanzani-tscheckst-des', 'Mit deina Aubergine kaunnst di glei schleichn - bei uns gibds Melanzani, Oida, MELANZANI! Tscheckst des?', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Mit deiner ''Aubergine'' kannst du dich gleich schleich’n. Bei uns gibt’s Melanzani, Alter – MELANZANI! Checkst du das?', '[{"kategorie": "wörtlich", "text": "\"Hau ab mit deiner ''Aubergine'' - in Wien sagt man MELANZANI, du Gemüse-Dodel!\"  2. Bei ''Aubergine'' krieg ich Gänsehaut und Magenschmerzen - sag g’scheit Melanzani, oder du bist g’sperrt fürs Beisl!  3. Eine Aubergine kannst in Piefkenäsien futtern, aber nicht bei uns in Wien - da heißt die Eierfrucht immer noch MELANZANI, du Dillo!"}]'::jsonb, ''),
  ('des-mentsch-is-sei-tochta', 'Des Mentsch is sei Tochta!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das Mentsch ist seine Tochter!', '[{"kategorie": "wörtlich", "text": "\"Das Mädchen ist seine Tochter!\"  2. Die Kleine ist seine leibliche Tochter!  3. Das Mädel ist seine eigene Tochter!"}]'::jsonb, ''),
  ('dea-schaud-an-jeedn-mentsch-untan-kiidl', 'Dea schaud an jeedn Mentsch untan Kiidl!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der schaut einem jeden Mentsch unter den Kittel!', '[{"kategorie": "wörtlich", "text": "\"Der schaut jedem Mädchen unter den Rock!\"  2. Der blickt allen jungen Frauen unter die Schürze!  3. Der schaut jeder Dienstmagd unter den Kittel!"}]'::jsonb, ''),
  ('na-seavas-bei-dia-schauds-aus-wiar-in-ana-mentschakaumma-ausn-19-joahundad-nua-mit-wlan-hoid', 'Na seavas, bei dia schauds aus wiar in ana Mentschakaumma ausn 19. Joahundad - nua mit WLAN hoid!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Na servus, bei dir schaut''s aus wie in einer Mentscherkammer aus’m 19. Jahrhundert – nur mit WLAN halt!', '[{"kategorie": "wörtlich", "text": "\"Na servus, bei dir sieht''s aus wie in einem Mägdezimmer aus’m 19. Jahrhundert – nur mit WLAN halt!\"  2. Wow, bei dir schaut''s aus wie in einem Dienstmädchenzimmer von der [[Urli]] – nur halt mit WLAN!  3. Allerhand, bei dir sieht''s aus wie in einem alten Dienstbotenzimmer – bloß mit Steckdosenleiste und WLAN!"}]'::jsonb, ''),
  ('heast-oida-bist-komplett-maeschuggae-des-mentsch-kaunnsd-doch-ned-heiratn', 'Heast Oida, bist komplett mäschuggä? - Des Mentsch kaunnsd doch ned heiratn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Hör mal, Alter, bist du komplett meschugge? Dieses Mentsch kannst du doch nicht heiraten!', '[{"kategorie": "wörtlich", "text": "\"Mensch, Alter, bist du komplett von Sinnen? Dieses Mädchen kannst du doch nicht heiraten!\"  2. Sag mal, Alter, spinnst du komplett? Du kannst dieses Mädchen doch nicht heiraten!  3. Alter, hast du sie noch alle? Die kannst du doch nicht heiraten!"}]'::jsonb, ''),
  ('a-woonung-im-mezzanin-woa-friara-a-statussymboi-ned-z-hoch-ned-z-niedrich-und-mit-aussicht', 'A Woonung im Mezzanin woa friara a Statussymboi - ned z''hoch, ned z''niedrich und mit Aussicht!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Eine Wohnung im Mezzanin war früher ein Statussymbol – nicht zu hoch, nicht zu niedrig, und mit Aussicht!', '[{"kategorie": "wörtlich", "text": "\"Eine Wohnung im Mezzanin galt früher als Statussymbol – nicht zu hoch, nicht zu niedrig, und mit Aussicht!\"  2. Das Mezzanin galt einst als bevorzugte Wohnlage – zentral gelegen zwischen Erdgeschoss und Oberstock, mit guter Aussicht!  3. Eine Bleibe im Mezzanin war früher das stille Privileg des gehobenen Bürgertums – standesgemäß wohnen mit Blick auf die Welt, aber ohne mühsames Treppensteigen!"}]'::jsonb, ''),
  ('beletaasch-geschooss', 'Beletaasch-Geschooss', 'die', '', '', 'Wiener Architektur & Baukunst', 'Beletage', '[{"kategorie": "allg.", "text": "Begriff aus der Architektur, der das repräsentativste und meist luxuriöseste Geschoss eines Wohnhauses, insbesondere in Gebäuden aus der Barockzeit, dem [[Klassizismus]] und der [[Gründerzeit]] bezeichnet (auch „Belle Étage“ genannt). Der Begriff stammt aus dem Französischen und bedeutet wörtlich „schöne Etage“ oder „schönes Geschoss“"}, {"kategorie": "", "text": "Die Beletage befindet sich in der Regel im ersten Obergeschoss, also eine Etage über dem Erdgeschoss. Diese Lage galt als besonders vorteilhaft, da sie leicht zu erreichen war, gute Lichtverhältnisse bot und den Lärm und Staub der Straße etwas abschirmte. In einigen Fällen kann die Beletage auch im zweiten Obergeschoss liegen, wenn das erste Obergeschoss eine andere, weniger repräsentative Funktion hatte"}, {"kategorie": "", "text": "Die Beletage zeichnet sich durch hohe Decken, großzügige Raumaufteilung und eine aufwendige Ausstattung aus. Sie war oft mit prächtigen Stuckverzierungen, großen Fenstern, Marmorböden und hochwertigen Wandverkleidungen versehen"}, {"kategorie": "", "text": "Die Räume in der Beletage waren häufig besonders repräsentativ gestaltet, mit Salons, Empfangsräumen und großen Esszimmern, die für gesellschaftliche Anlässe genutzt wurden"}, {"kategorie": "", "text": "In der Architektur der [[Gründerzeit]] und früherer Epochen war die Beletage ein Symbol für den sozialen Status der Bewohner. Eine luxuriös ausgestattete Beletage zeugte vom Wohlstand und der gesellschaftlichen Stellung der Familie"}]'::jsonb, ''),
  ('friara-woa-de-beletaasch-wos-fian-oodl-heit-woonan-duat-hipsta-mit-vintaedsch-kautsch-und-bilaetti', 'Friara woa de Beletaasch wos fian Oodl - heit woonan duat Hipsta mit Vintädsch-Kautsch und Bilaetti!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Früher war die Beletage was für Adel, heute wohnen dort Hipster mit Vintage-Couch und Bialetti!', '[{"kategorie": "wörtlich", "text": "\"Einst war die Beletage den adeligen Herrschaften vorbehalten – heute wohnen dort junge Kreative mit Retro-Möbeln und Espressokochern!\"  2. Was früher das repräsentative Stockwerk für den Adel war, ist heute die Spielwiese der Hipster mit Altbau-Charme und Designkaffee!  3. Die Beletage gehörte einst den Reichen und Mächtigen – heute füllen sie Hipster mit Flohmarktcouch und Espressokännchen!"}]'::jsonb, ''),
  ('kaum-dassara-mistlbocha-wuan-is-isa-si-aa-schon-vuakumma-wiara-hoeoed', 'Kaum dassara Mistlbocha wuan is, isa si aa schon vuakumma wiara Hööd!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Kaum dass er ein Mistelbacher geworden ist, ist er sich auch schon vorgekommen wie ein Held!', '[{"kategorie": "wörtlich", "text": "\"Kaum dass er Wachmann war, ist er sich wie ein Held vorgekommen!\"  2. Kaum in Uniform, hielt er sich bereits für einen Helden!  3. Kaum hatte er die Polizistenjacke an, fühlte er sich schon wie Superman!"}]'::jsonb, ''),
  ('bei-uns-dahaam-soogd-kaana-papiakoab-des-is-a-mistkiiwae-und-wea-wos-aundas-soogd-kriagd-a-waatschn', 'Bei uns dahaam soogd kaana ''Papiakoab'' - des is a Mistkiiwä, und wea wos aundas soogd, kriagd a Waatschn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Bei uns daheim sagt keiner ‚Papierkorb‘ – das ist ein Mistkübel, und wer was anderes sagt, kriegt eine Watschen!', '[{"kategorie": "wörtlich", "text": "\"Bei uns zu Hause sagt niemand ‚Papierkorb‘ – das ist ein Mistkübel, und wer was anderes sagt, fängt sich sofort eine Ohrfeige ein!\"  2. Wer bei uns daheim ‚Papierkorb‘ sagt, landet gleich selbst im Mistkübel!  3. Bei uns daheim gibt es keinen Papierkorb, sondern nur den Mistkübel – und wer''s falsch sagt, fliegt gleich selbst kopfüber rein!"}]'::jsonb, ''),
  ('da-beatl-is-a-menschlicha-mistkiiwae-dea-frissd-ollas-wos-eam-vuad-goschn-kummd', 'Da Beatl is a menschlicha Mistkiiwä - dea frissd ollas, wos eam vuad Goschn kummd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Bertl ist ein menschlicher Mistkübel - der frisst alles, was ihm vor die Goschen kommt!', '[{"kategorie": "wörtlich", "text": "\"Der Bertl ist ein Allesfresser – der isst wirklich alles, was man ihm hinstellt!\"  2. Der Bertl ist ein menschlicher Abfalleimer – alles, was vor sein Maul kommt, haut er rein!  3. Wenn der Bertl am Tisch sitzt, brauchst du keinen Mistkübel mehr – der saugt alles auf, was vor ihm liegt!"}]'::jsonb, ''),
  ('wueuesd-mi-moschaln', 'Wüüsd mi moschaln?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Willst du mich moscherln?', '[{"kategorie": "wörtlich", "text": "\"Willst du mich ärgern?\"  2. Willst du mich verarschen?  3. Nerv mich nur ja nicht!  3."}]'::jsonb, ''),
  ('du-kaunnst-mi-moschaln', 'Du kaunnst mi moschaln!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du kannst mich moscherln!', '[{"kategorie": "wörtlich", "text": "\"Du kannst mich gern haben!\"  2. \"Du kannst mir den Buckel runterrutschen!\"  3. \"Du kannst mich mal kreuzweise!\""}]'::jsonb, ''),
  ('den-schuach-ziag-i-ma-sicha-ned-au', 'Den Schuach ziag I ma sicha ned au!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Diesen Schuh zieh ich mir sicher nicht an!', '[{"kategorie": "wörtlich", "text": "\"Dafür übernehme ich sicher nicht die Verantwortung!\"  2. \"Das lass ich mir sicher nicht anhängen!\"  3. \"Diesen Mantel leg ich mir sicher nicht um!\"  4. \"Den schwarzen Peter lass ich mir sicher nicht zuschieben!\""}]'::jsonb, ''),
  ('ob-vagoan-oda-unvagoan-most-is-mit-und-oone-alkohol-a-tropfn-hoamat-im-glaasl', 'Ob vagoan oda unvagoan, Most is mit und oone Alkohol a Tropfn Hoamat im Glaasl!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ob vergoren oder unvergoren, Most ist mit und ohne Alkohol ein Tropfen Heimat im Glas!', '[{"kategorie": "wörtlich", "text": "\"Egal ob vergoren oder frisch gepresst – Most bleibt, mit oder ohne Alkohol, ein Stück Tradition im Glas!\"  2. Ob süß oder herb, mit oder ohne Alkohol – Most ist immer ein Schluck Heimat pur!  3. Ob jung, spritzig oder kräftig vergoren – Most ist der Geschmack von Erde, Obstgarten und Heimat!"}]'::jsonb, ''),
  ('mit-de-mostschaeaedln-kaunnst-reedn-saufn-streitn-hauptsoch-da-most-geed-ned-aus', 'Mit de Mostschäädln kaunnst reedn, saufn, streitn - Hauptsoch, da Most geed ned aus!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mit den Mostschädeln kannst du reden, saufen, streiten – Hauptsache, der Most geht nicht aus!', '[{"kategorie": "wörtlich", "text": "\"Mit den Oberösterreichern kannst du diskutieren, feiern oder streiten – solange der Most fließt!\"  2. Ob reden, trinken oder streiten – mit den Mostschädeln geht alles, solange genug Most da ist!  3. Mit den Mostschädeln kannst du über Gott und die Welt reden, dich anpöbeln oder besaufen – nur der Most darf nie fehlen!"}]'::jsonb, ''),
  ('fiad-hollaenda-is-jeeda-klaane-mugl-schoo-a-beag', 'Fiad Hollända is jeeda klaane Mugl schoo a Beag!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Für die Holländer ist jeder kleine Mugel schon ein Berg!', '[{"kategorie": "wörtlich", "text": "\"Für die Holländer ist jeder kleine Hügel schon ein Berg!\"  2. Für Holländer ist jede Bodenerhebung gleich ein Gebirge!  3. In Holland sagen sie schon zu einem Maulwurfshügel ''Berg''!"}]'::jsonb, ''),
  ('in-unsara-woonschdrossn-haums-jetzt-lauta-muugln-eibaud-sogoa-de-raadlfoara-fluachn-schoo', 'In unsara Woonschdrossn haums jetzt lauta Muugln eibaud - sogoa de Raadlfoara fluachn schoo!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'In unserer Wohnstraße haben sie jetzt lauter Mugeln eingebaut - sogar die Radfahrer fluchen schon!', '[{"kategorie": "wörtlich", "text": "\"In unserer Wohnstraße haben sie jetzt mehrere Bodenwellen eingebaut – sogar die Radfahrer fluchen schon!\"  2. Unsere Wohnstraße ist jetzt eine Buckelpiste – da jammern sogar die Radfahrer!  3. In unserer Gasse sind jetzt so viele Stoßdämpferkiller verbaut, dass sogar die Radfahrer fluchen!"}]'::jsonb, ''),
  ('an-muugl-rausch-haum', 'an muugl Rausch haum', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'einen mugel Rausch haben', '[{"kategorie": "wörtlich", "text": "\"einen Vollrausch haben\""}, {"kategorie": "", "text": "\"einen kapitalen Rausch haben\""}, {"kategorie": "", "text": "\"voll im Öl sein\""}, {"kategorie": "", "text": "\"in der Vollglut sein\""}, {"kategorie": "", "text": "sturzbetrunken, stockbesoffen, sternhagelvoll sein"}]'::jsonb, ''),
